INSERT INTO _teaser_card_plan (site_id, column_name, old_value, new_value, change_key, reason, premise, evidence) VALUES
    ('e34f699d-7025-4f41-ab0c-fdb54d6a672c'::uuid, 'card_description', 'Less than a mile east of the main ruins at Delphi, twenty Doric columns ringed the circular Tholos of Delphi, and its metopes showed scenes from Amazon and Centaur battles.', 'A circular tholos at the Sanctuary of Athena Pronaia. Its three restored columns are among the most photographed images from all of the ancient world.', 'teaser-card-s016-rollback:e34f699d-7025-4f41-ab0c-fdb54d6a672c:card_description', 'rollback of teaser-card-s016: card_description ''A circular tholos at the Sanctuary of Athena Pronaia. Its three restored columns are among the most photographed images from all of the ancient world.'' restored on Tholos of Delphi', '993f8a59b6760e5c384d6c1d0dd89fdbd264440d0b8ef8c0f3584d66ac780e14|85b51f3471d2f18cd025f8bc1f4087aa2a21a6b2904a502acdc7481779b90ba7|85b51f3471d2f18cd025f8bc1f4087aa2a21a6b2904a502acdc7481779b90ba7', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-027", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Less than a mile east of the main ruins at Delphi, twenty Doric columns ringed the circular Tholos of Delphi, and its metopes showed scenes from Amazon and Centaur battles."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-027 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the Tholos of Delphi lies less than a mile east of the main ruins at Delphi [S2]; twenty Doric columns stood around the outside [S4]; the Tholos is circular [S2]; its metopes showed scenes from Amazon battles [S6]; its metopes showed scenes from Centaur battles [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-081 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Tholos of Delphi is a circular temple (a tholos) among the ancient structures at Delphi, Greece [SUPPORTED: https://en.wikipedia.org/wiki/Tholos_of_Delphi]; It lies less than a mile east of the main ruins at Delphi [SUPPORTED: https://en.wikipedia.org/wiki/Tholos_of_Delphi]; The tholos had twenty columns on its exterior, ringing the building [SUPPORTED: https://en.wikipedia.org/wiki/Tholos_of_Delphi]; The columns were of the Doric order [SUPPORTED: https://en.wikipedia.org/wiki/Tholos_of_Delphi]; The tholos had metopes with figural scenes on its outer side [SUPPORTED: https://en.wikipedia.org/wiki/Tholos_of_Delphi]; The metopes showed scenes from Amazon battles [SUPPORTED: https://en.wikipedia.org/wiki/Tholos_of_Delphi]; The metopes showed scenes from Centaur battles [SUPPORTED: https://en.wikipedia.org/wiki/Tholos_of_Delphi]"}]'::jsonb),
    ('e427d7bf-01bd-4238-b972-b0ff62511a9e'::uuid, 'card_description', 'Near the hills of Kyffhäuser, the Leubingen Tumulus, an Early Bronze Age princely grave of about 1940 BC, still rises 7 metres. At its centre lay the body of a man about 50 years old.', 'A ''princely'' grave from 1940 BC with a timber chamber under a massive earth mound. Gold jewelry and bronze weapons mark it as one of the richest Bronze Age burials in Central Europe.', 'teaser-card-s016-rollback:e427d7bf-01bd-4238-b972-b0ff62511a9e:card_description', 'rollback of teaser-card-s016: card_description "A ''princely'' grave from 1940 BC with a timber chamber under a massive earth mound. Gold jewelry and bronze weapons mark it as one of the richest Bronze Age burials in Central Europe." restored on Leubingen Tumulus', '36e67eac5c56fe6c3a2b33f8889a27fcddcc07c2b37de9dc8eff3b80fee5af21|d426a43793a50e724478e0a44b5841acc1868ff5a19a74cbad167dfe5f56e32b|d426a43793a50e724478e0a44b5841acc1868ff5a19a74cbad167dfe5f56e32b', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-027", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Near the hills of Kyffhäuser, the Leubingen Tumulus, an Early Bronze Age princely grave of about 1940 BC, still rises 7 metres. At its centre lay the body of a man about 50 years old."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-027 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the Leubingen Tumulus lies near the hills of Kyffhäuser [S2]; it is an Early Bronze Age princely grave [S1]; it dates to about 1940 BC [S1]; the mound still rises 7 metres [S4, S5]; the body of a man lay at its centre [S6]; the man was about 50 years old [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-081 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Leubingen Tumulus is an Early Bronze Age princely grave (a burial mound) in Germany [SUPPORTED: https://en.wikipedia.org/wiki/Leubingen_tumulus]; It lies near the hills of Kyffhäuser [SUPPORTED: https://en.wikipedia.org/wiki/Leubingen_tumulus]; The grave dates to about 1940 BC [SUPPORTED: https://en.wikipedia.org/wiki/Leubingen_tumulus]; The mound still rises 7 metres [SUPPORTED: https://en.wikipedia.org/wiki/Leubingen_tumulus]; At the centre of the grave lay a body [SUPPORTED: https://en.wikipedia.org/wiki/Leubingen_tumulus]; The body at the centre was that of a man [SUPPORTED: https://en.wikipedia.org/wiki/Leubingen_tumulus]; The man was about 50 years old [SUPPORTED: https://en.wikipedia.org/wiki/Leubingen_tumulus]"}]'::jsonb),
    ('e45af002-3182-479c-984e-0692325c40c7'::uuid, 'card_description', 'In Benevento, the Roman Theatre that Hadrian built in 126 AD was abandoned in Lombard times and is now surrounded by the medieval Triggio district. One passage keeps its mosaic pavement.', 'A 2nd-century AD theatre built by Emperor Hadrian, surrounded by the medieval quarter that grew around its ruins. It is still used for performances.', 'teaser-card-s016-rollback:e45af002-3182-479c-984e-0692325c40c7:card_description', 'rollback of teaser-card-s016: card_description ''A 2nd-century AD theatre built by Emperor Hadrian, surrounded by the medieval quarter that grew around its ruins. It is still used for performances.'' restored on Roman Theatre, Benevento', 'ee2e2e8181c24e93ccfdd19e98f8f1f547263bccb98bdb0901fadccc319feda6|a8ef3ecdbf695cf41ca3f6a842220923adc795f5031a39649955524d148edeb5|a8ef3ecdbf695cf41ca3f6a842220923adc795f5031a39649955524d148edeb5', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-rewrite-v-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "In Benevento, the Roman Theatre that Hadrian built in 126 AD was abandoned in Lombard times and is now surrounded by the medieval Triggio district. One passage keeps its mosaic pavement."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-v-003 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the Roman Theatre is in Benevento [S1]; the emperor Hadrian built the theatre [S2]; it was built in 126 AD [S2]; it was abandoned in Lombard times [S3]; it is now surrounded by the Triggio district [S3]; the Triggio district is medieval [S3]; one of the parodoi (side passages at the orchestra) keeps its mosaic pavement [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify2-007 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The site is an ancient Roman theatre (central claim: what kind of place it is) [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Theatre,_Benevento]; It is in Benevento (southern Italy) [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Theatre,_Benevento]; The emperor Hadrian built it [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Theatre,_Benevento]; It was built in 126 AD [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Theatre,_Benevento]; It was abandoned in Lombard times [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Theatre,_Benevento]; It is now surrounded by the medieval Triggio district [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Theatre,_Benevento]; One passage (parodos) keeps its mosaic pavement [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Theatre,_Benevento]"}]'::jsonb),
    ('e4b003f4-3f62-4689-9af9-4b7f120614af'::uuid, 'card_description', 'Ptolemy''s Geographia names a town, Navalia, recently linked to Essen. Its name translates from Latin as dock or wharf, maybe by coincidence, and copyists'' mistakes polluted its coordinates.', '1st century AD. Recorded by Ptolemy in his Geographia — its Latin name meaning ''dock'' or ''wharf'', recently linked to Essen. Exact coordinates remain uncertain due to ancient scribal copying errors.', 'teaser-card-s016-rollback:e4b003f4-3f62-4689-9af9-4b7f120614af:card_description', 'rollback of teaser-card-s016: card_description "1st century AD. Recorded by Ptolemy in his Geographia — its Latin name meaning ''dock'' or ''wharf'', recently linked to Essen. Exact coordinates remain uncertain due to ancient scribal copying errors." restored on Navalia', '8f1424467f3e8f17d6baf15e090e2f3bf6d1b18499dca8ab2165311f9ad380bc|e5bce4b9567c10cd00b29958b86a796feefda2ccdd880947cc1523fbb3ce61c8|e5bce4b9567c10cd00b29958b86a796feefda2ccdd880947cc1523fbb3ce61c8', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-027", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Ptolemy''s Geographia names a town, Navalia, recently linked to Essen. Its name translates from Latin as dock or wharf, maybe by coincidence, and copyists'' mistakes polluted its coordinates."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-027 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Ptolemy''s Geographia names a town, Navalia [S1]; the town has recently been linked to Essen [S2]; the name translates from Latin as dock or wharf [S3]; the dock or wharf meaning may be coincidental [S3]; copyists'' mistakes polluted its coordinates [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-081 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Navalia is a town (polis or oppidum) named in Ptolemy''s Geographia [SUPPORTED: https://en.wikipedia.org/wiki/Navalia]; Navalia has recently been linked to Essen [SUPPORTED: https://en.wikipedia.org/wiki/Navalia]; Essen is the modern city identified with Ptolemy''s Navalia (Berlin TU research) [SUPPORTED: http://www.spiegel.de/international/zeitgeist/mapping-ancient-germania-berlin-researchers-crack-the-ptolemy-code-a-720513.html]; Its name translates from Latin as dock or wharf [SUPPORTED: https://en.wikipedia.org/wiki/Navalia]; The dock/wharf meaning of the name may be a coincidence [SUPPORTED: https://en.wikipedia.org/wiki/Navalia]; Copyists'' mistakes polluted Ptolemy''s coordinates for the town [SUPPORTED: https://en.wikipedia.org/wiki/Navalia]"}]'::jsonb),
    ('e4f6fa32-6aff-4539-b40b-ab73f9e94cec'::uuid, 'card_description', 'At Sammallahdenmäki in Rauma, the Kirkonlaattia, or Church Floor, is a rectangular cairn of granite boulders covering 16 x 19 metres, with a flat top. Volter Högman excavated it in 1891.', 'Thirty-three granite burial cairns near Rauma, dated 1500–500 BC — the most complete Bronze Age burial landscape in Fennoscandia. UNESCO listed the site in 1999.', 'teaser-card-s016-rollback:e4f6fa32-6aff-4539-b40b-ab73f9e94cec:card_description', 'rollback of teaser-card-s016: card_description ''Thirty-three granite burial cairns near Rauma, dated 1500–500 BC — the most complete Bronze Age burial landscape in Fennoscandia. UNESCO listed the site in 1999.'' restored on Sammallahdenmäki', '9cdb984db747f811392db4bb6d187c3595e100f3bcd80b235988b98fe0f86dd1|9d4e0e24dd188bcbded2e9b7c59c7951f071936efbf6f25a8e808c5bf41bd97b|9d4e0e24dd188bcbded2e9b7c59c7951f071936efbf6f25a8e808c5bf41bd97b', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-rewrite-v-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "At Sammallahdenmäki in Rauma, the Kirkonlaattia, or Church Floor, is a rectangular cairn of granite boulders covering 16 x 19 metres, with a flat top. Volter Högman excavated it in 1891."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-v-003 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Sammallahdenmäki is in Rauma [S1]; the Kirkonlaattia is also called Church Floor [S5]; the Kirkonlaattia is a cairn at Sammallahdenmäki [S3, S5]; the Kirkonlaattia is rectangular [S5]; the cairn is built of granite boulders [S4]; it covers 16 x 19 metres [S5]; it has a flat top [S5]; Volter Högman excavated it [S6]; the excavation was in 1891 [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify2-007 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Sammallahdenmäki is a Bronze Age burial site of cairns in Rauma, Finland (central claim: what kind of place and where) [SUPPORTED: https://en.wikipedia.org/wiki/Sammallahdenm%C3%A4ki]; The Kirkonlaattia is a cairn at Sammallahdenmäki [SUPPORTED: https://en.wikipedia.org/wiki/Sammallahdenm%C3%A4ki]; Kirkonlaattia means Church Floor [SUPPORTED: https://en.wikipedia.org/wiki/Sammallahdenm%C3%A4ki]; The Kirkonlaattia cairn is rectangular [SUPPORTED: https://en.wikipedia.org/wiki/Sammallahdenm%C3%A4ki]; The cairn is made of granite boulders [SUPPORTED: https://en.wikipedia.org/wiki/Sammallahdenm%C3%A4ki]; The cairn covers 16 x 19 metres [SUPPORTED: https://en.wikipedia.org/wiki/Sammallahdenm%C3%A4ki]; The cairn has a flat top [SUPPORTED: https://en.wikipedia.org/wiki/Sammallahdenm%C3%A4ki]; Volter Högman excavated the Kirkonlaattia [SUPPORTED: https://en.wikipedia.org/wiki/Sammallahdenm%C3%A4ki]; The excavation took place in 1891 [SUPPORTED: https://en.wikipedia.org/wiki/Sammallahdenm%C3%A4ki]"}]'::jsonb),
    ('e59e7ff4-2392-4365-ab67-2b7fc0d90472'::uuid, 'card_description', 'Buried deep in the Late Classic Acropolis of Copán, the Margarita Tomb held a Maya woman''s remains covered in cinnabar and hematite, a vaulted stairway joining its upper and lower chambers.', 'Around 500 AD. Buried deep in Copán''s Late Classic acropolis, the Margarita Tomb held one of the largest caches ever found with a Maya woman''s burial — she was almost certainly royalty.', 'teaser-card-s016-rollback:e59e7ff4-2392-4365-ab67-2b7fc0d90472:card_description', 'rollback of teaser-card-s016: card_description "Around 500 AD. Buried deep in Copán''s Late Classic acropolis, the Margarita Tomb held one of the largest caches ever found with a Maya woman''s burial — she was almost certainly royalty." restored on Margarita Tomb', 'c31533ced1f1b085097c5e6c842b2f670332ad309503207d9831ce65cf5f5813|7a0d0e9932e3526cfde2136433933f14530cac417725cdb69541053511ad57fa|7a0d0e9932e3526cfde2136433933f14530cac417725cdb69541053511ad57fa', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-028", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Buried deep in the Late Classic Acropolis of Copán, the Margarita Tomb held a Maya woman''s remains covered in cinnabar and hematite, a vaulted stairway joining its upper and lower chambers."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-028 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the site is the Margarita Tomb [S1]; it lies buried deep in the Acropolis of Copán [S1]; the Acropolis is Late Classic [S1]; the tomb held the remains of a Maya woman [S2, S3]; the remains were covered in cinnabar and hematite [S3]; the tomb has an upper chamber and a lower chamber [S2, S4]; a vaulted stairway joins the upper and lower chambers [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-082 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Margarita Tomb is a tomb, located in the Late Classic Acropolis of Copán (Honduras) [SUPPORTED: https://en.wikipedia.org/wiki/Margarita_Tomb]; The tomb lies buried deep inside the Acropolis [SUPPORTED: https://en.wikipedia.org/wiki/Margarita_Tomb]; The Acropolis in which the tomb lies is the Late Classic Acropolis of Copán [SUPPORTED: https://en.wikipedia.org/wiki/Margarita_Tomb]; The tomb held a woman''s remains [SUPPORTED: https://en.wikipedia.org/wiki/Margarita_Tomb]; The woman buried in the tomb was Maya [SUPPORTED: https://en.wikipedia.org/wiki/Margarita_Tomb]; The remains were covered in cinnabar [SUPPORTED: https://en.wikipedia.org/wiki/Margarita_Tomb]; The remains were covered in hematite [SUPPORTED: https://en.wikipedia.org/wiki/Margarita_Tomb]; The tomb has a vaulted stairway [SUPPORTED: https://en.wikipedia.org/wiki/Margarita_Tomb]; The tomb has an upper and a lower chamber, and the vaulted stairway joins them [SUPPORTED: https://en.wikipedia.org/wiki/Margarita_Tomb]"}]'::jsonb),
    ('e5efe12c-25a8-423f-8974-98fc23e299e9'::uuid, 'card_description', 'Almost 100 meters long and lined with Doric columns, the Echo Stoa stands in the sanctuary of Zeus at Olympia. It is said one word uttered in its hall would echo seven times.', 'A 4th-century BC covered walkway at Olympia, named for the sevenfold echo its colonnade produced. Spectators gathered here during the ancient Olympic Games.', 'teaser-card-s016-rollback:e5efe12c-25a8-423f-8974-98fc23e299e9:card_description', 'rollback of teaser-card-s016: card_description ''A 4th-century BC covered walkway at Olympia, named for the sevenfold echo its colonnade produced. Spectators gathered here during the ancient Olympic Games.'' restored on Echo Stoa', 'b114258e4a9a35341ee973c057105f55c8a5e68b82d3f22d9a16b86904671960|59a398afb27e0f95fae3bedc84eb0804fd85e28979179ad2afeb2dd24b7d2f3b|59a398afb27e0f95fae3bedc84eb0804fd85e28979179ad2afeb2dd24b7d2f3b', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-028", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Almost 100 meters long and lined with Doric columns, the Echo Stoa stands in the sanctuary of Zeus at Olympia. It is said one word uttered in its hall would echo seven times."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-028 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the Echo Stoa is almost 100 metres long [S5]; it is lined with Doric columns [S5]; it stands in the sanctuary of Zeus [S1]; the sanctuary is at Olympia [S1]; it is said that one word uttered in the stoa''s hall would echo seven times [S3, S4]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-082 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Echo Stoa is a stoa (colonnaded portico) located in the sanctuary of Zeus at Olympia, Greece [SUPPORTED: https://en.wikipedia.org/wiki/Echo_Stoa]; A stoa is a covered walkway or portico, typically colonnaded (so the Echo Stoa is a colonnaded hall) [SUPPORTED: https://en.wikipedia.org/wiki/Echo_Stoa]; The Echo Stoa stands at Olympia [SUPPORTED: https://en.wikipedia.org/wiki/Echo_Stoa]; The Echo Stoa is almost 100 meters long [SUPPORTED: https://en.wikipedia.org/wiki/Echo_Stoa]; The Echo Stoa is lined with Doric columns [SUPPORTED: https://en.wikipedia.org/wiki/Echo_Stoa]; It is said (tradition) that one word uttered in the hall would echo seven times [SUPPORTED: https://en.wikipedia.org/wiki/Echo_Stoa]; The stoa''s echo was reported in antiquity: the Portico is called the Echo Portico because a shout is repeated by the echo seven or even more times (Pausanias 5.21.17) [SUPPORTED: https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.01.0160:book=5:chapter=21:section=17]"}]'::jsonb),
    ('e60fc487-9fb9-4e37-b590-4a035e591c7e'::uuid, 'card_description', 'A flood destroyed its earliest version in the 7th century BC, an arsonist burned its more elaborate rebuilding in 356 BC, and still the Temple of Artemis-Selçuk at Ephesus rose again.', 'One of the Seven Wonders of the Ancient World, now reduced to a single reconstructed column. Three versions of this temple were built over a thousand years.', 'teaser-card-s016-rollback:e60fc487-9fb9-4e37-b590-4a035e591c7e:card_description', 'rollback of teaser-card-s016: card_description ''One of the Seven Wonders of the Ancient World, now reduced to a single reconstructed column. Three versions of this temple were built over a thousand years.'' restored on The Temple of Artemis-Selçuk', 'b26f89eb3db89a7db9c79ac1829e5947439943dcdde6d78d29cfd2c9fde015b6|76ee151b4f17bbabf33eb013b479cd3e2270cecaf6ccb0ddd5bf9448ff280c1b|76ee151b4f17bbabf33eb013b479cd3e2270cecaf6ccb0ddd5bf9448ff280c1b', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-028", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "A flood destroyed its earliest version in the 7th century BC, an arsonist burned its more elaborate rebuilding in 356 BC, and still the Temple of Artemis-Selçuk at Ephesus rose again."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-028 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "a flood destroyed the temple''s earliest version [S4]; the flood was in the 7th century BC [S4]; the temple had a more elaborate rebuilding [S5]; an arsonist burned that more elaborate version down [S6]; the burning was in 356 BC [S6]; the temple was at Ephesus [S2]; the temple rose again after the burning (a final form followed) [S6, S7]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-082 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Temple of Artemis at Ephesus (near modern Selçuk) was a Greek temple dedicated to the goddess Artemis [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Artemis]; The temple was located at Ephesus, by modern Selçuk [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Artemis]; The earliest version of the temple was destroyed by a flood [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Artemis]; The flood happened in the 7th century BC [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Artemis]; The temple was rebuilt in a more elaborate version after the flood [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Artemis]; An arsonist burned down that more elaborate rebuilding [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Artemis]; The burning happened in 356 BC [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Artemis]; The temple rose again: the Ephesians rebuilt it after the arson [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Artemis]"}]'::jsonb),
    ('e7c32c5c-3f26-483a-9d49-75ad5003c44b'::uuid, 'card_description', 'Found by chance in 1929 on the River Dee, the Heronbridge Roman Site had stone buildings and a quayside cut into the bedrock. Digs found human remains with evidence of violent deaths.', 'A Roman settlement with stone buildings and a quayside cut into bedrock. Industrial furnaces from the 1st century show it was a manufacturing hub, not just a town.', 'teaser-card-s016-rollback:e7c32c5c-3f26-483a-9d49-75ad5003c44b:card_description', 'rollback of teaser-card-s016: card_description ''A Roman settlement with stone buildings and a quayside cut into bedrock. Industrial furnaces from the 1st century show it was a manufacturing hub, not just a town.'' restored on Heronbridge Roman Site', 'de801953380d6e70de73d980866db776655af9ebde1ec0060524f0b5c038e563|56cb666d7e4f3c6d3bdbef030d783f77c9f2f8b959dc37c6be2d9e7922af166e|56cb666d7e4f3c6d3bdbef030d783f77c9f2f8b959dc37c6be2d9e7922af166e', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-028", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Found by chance in 1929 on the River Dee, the Heronbridge Roman Site had stone buildings and a quayside cut into the bedrock. Digs found human remains with evidence of violent deaths."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-028 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the site was found by chance [S2]; it was found in 1929 [S2]; it lies on the River Dee [S5]; the settlement had stone buildings [S6]; it had a quayside cut into the bedrock [S6]; excavations found human remains [S3]; the remains showed evidence of violent deaths [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-082 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Heronbridge Roman Site is the remains of a Roman settlement near Chester, England [SUPPORTED: https://en.wikipedia.org/wiki/Heronbridge_Roman_Site]; The site was found by chance [SUPPORTED: https://en.wikipedia.org/wiki/Heronbridge_Roman_Site]; The site was found in 1929 [SUPPORTED: https://en.wikipedia.org/wiki/Heronbridge_Roman_Site]; The site lies on the River Dee [SUPPORTED: https://en.wikipedia.org/wiki/Heronbridge_Roman_Site]; The Roman settlement had stone buildings [SUPPORTED: https://en.wikipedia.org/wiki/Heronbridge_Roman_Site]; The Roman settlement had a quayside cut into the bedrock [SUPPORTED: https://en.wikipedia.org/wiki/Heronbridge_Roman_Site]; Excavations at the site found human remains [SUPPORTED: https://en.wikipedia.org/wiki/Heronbridge_Roman_Site]; The human remains showed evidence of violent deaths [SUPPORTED: https://en.wikipedia.org/wiki/Heronbridge_Roman_Site]"}]'::jsonb),
    ('e7cc2c23-894f-456c-b88b-66bd9e52ad0f'::uuid, 'card_description', 'In the prefecture of Evros lies the Macedonian Tomb of Elafochori, dating to the end of the 4th century BC: a tomb of the Macedonian type, yet with special morphological features of its own.', '4th century BC. Discovered by accident, this Macedonian-type tomb near Elafochori has distinct Thracian features — an early Hellenistic burial believed to hold a figure of local importance.', 'teaser-card-s016-rollback:e7cc2c23-894f-456c-b88b-66bd9e52ad0f:card_description', 'rollback of teaser-card-s016: card_description ''4th century BC. Discovered by accident, this Macedonian-type tomb near Elafochori has distinct Thracian features — an early Hellenistic burial believed to hold a figure of local importance.'' restored on Macedonian Tomb of Elafochori', '8a9e12db129a891653765bcb8f8c4ea754f2c3587bf2ca92c3ea2e7a7257a398|17bba2bf2075d7bb562b064d1335580f458b5c6b2c1ccf7075f58514bef91d76|17bba2bf2075d7bb562b064d1335580f458b5c6b2c1ccf7075f58514bef91d76', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-028", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "In the prefecture of Evros lies the Macedonian Tomb of Elafochori, dating to the end of the 4th century BC: a tomb of the Macedonian type, yet with special morphological features of its own."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-028 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the tomb lies in the prefecture of Evros [S1]; it dates to the end of the 4th century BC [S3]; it is a tomb of the Macedonian type [S2]; it has special morphological features [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-082 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Macedonian Tomb of Elafochori is an archaeological monument, a tomb, near the settlement of Elafochori in Greece [SUPPORTED: https://en.wikipedia.org/wiki/Macedonian_tomb_of_Elafochori]; The tomb lies in the prefecture of Evros [SUPPORTED: https://en.wikipedia.org/wiki/Macedonian_tomb_of_Elafochori]; The tomb dates to the end of the 4th century BC [SUPPORTED: https://en.wikipedia.org/wiki/Macedonian_tomb_of_Elafochori]; It is a tomb of the Macedonian type [SUPPORTED: https://en.wikipedia.org/wiki/Macedonian_tomb_of_Elafochori]; It has special morphological features of its own [SUPPORTED: https://en.wikipedia.org/wiki/Macedonian_tomb_of_Elafochori]"}]'::jsonb),
    ('e8235f8c-e30c-4c97-8297-639b2681d46b'::uuid, 'card_description', 'Near the Malangen fjord, a hunting culture left the Rock Carvings at Åsli: at least 15 worn figures, among them at least eight reindeer, porpoise, a boat and possibly a moose.', 'The rock carvings at Åsli are located near the Malangen fjord in Balsfjord Municipality in Troms county.', 'teaser-card-s016-rollback:e8235f8c-e30c-4c97-8297-639b2681d46b:card_description', 'rollback of teaser-card-s016: card_description ''The rock carvings at Åsli are located near the Malangen fjord in Balsfjord Municipality in Troms county.'' restored on Rock Carvings at Åsli', 'f6612bf579f5b53c3f773976a5d281489cc082250b1dfbc9a8a77bb1fed3ae18|d93815fc024bbe019db48a39127abc2f57bd004413e74c016af1fb51e63f770f|d93815fc024bbe019db48a39127abc2f57bd004413e74c016af1fb51e63f770f', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-028", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Near the Malangen fjord, a hunting culture left the Rock Carvings at Åsli: at least 15 worn figures, among them at least eight reindeer, porpoise, a boat and possibly a moose."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-028 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the carvings are near the Malangen fjord [S1]; a hunting culture made the carvings [S3]; there are at least 15 figures [S2]; the figures are worn (in poor condition) [S2]; at least eight of the figures are reindeer [S4]; there are figures of porpoise [S5]; there is a figure of a boat [S5]; there is possibly a figure of a moose [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-083 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Rock Carvings at Åsli are a rock-carving (petroglyph) site [SUPPORTED: https://en.wikipedia.org/wiki/Rock_carvings_at_%C3%85sli]; The site lies near the Malangen fjord (Norway) [SUPPORTED: https://en.wikipedia.org/wiki/Rock_carvings_at_%C3%85sli]; The carvings were made by a hunting culture [SUPPORTED: https://en.wikipedia.org/wiki/Rock_carvings_at_%C3%85sli]; There are at least 15 figures [SUPPORTED: https://en.wikipedia.org/wiki/Rock_carvings_at_%C3%85sli]; The figures are worn (in poor condition) [SUPPORTED: https://en.wikipedia.org/wiki/Rock_carvings_at_%C3%85sli]; At least eight of the figures are reindeer [SUPPORTED: https://en.wikipedia.org/wiki/Rock_carvings_at_%C3%85sli]; There are figures of porpoise [SUPPORTED: https://en.wikipedia.org/wiki/Rock_carvings_at_%C3%85sli]; There is a figure of a boat [SUPPORTED: https://en.wikipedia.org/wiki/Rock_carvings_at_%C3%85sli]; One figure is possibly a moose [SUPPORTED: https://en.wikipedia.org/wiki/Rock_carvings_at_%C3%85sli]"}]'::jsonb),
    ('e8ecb6c3-4f2c-4505-9b66-ac3743b02e54'::uuid, 'card_description', 'On a hill in ancient Colchis, the Vani Archaeological Site gave up a 4th-century BC signet-ring bearing the name of Dedatos, probably a local ruler. The city''s ancient name is unknown.', 'The best-studied site in ancient Colchis, inscribed as a national cultural monument. Excavations revealed temples, fortifications, and gold jewelry of exceptional craftsmanship.', 'teaser-card-s016-rollback:e8ecb6c3-4f2c-4505-9b66-ac3743b02e54:card_description', 'rollback of teaser-card-s016: card_description ''The best-studied site in ancient Colchis, inscribed as a national cultural monument. Excavations revealed temples, fortifications, and gold jewelry of exceptional craftsmanship.'' restored on Vani Archaeological Site', '678a4e85d4e7cd8c7ffc4aa0bbe562194fecf432a77c81ef916fb54d871bcd16|338152db1ed818f682a0b7fe619cab16f9c2de8c53872b13ced86e6601c8073c|338152db1ed818f682a0b7fe619cab16f9c2de8c53872b13ced86e6601c8073c', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-028", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "On a hill in ancient Colchis, the Vani Archaeological Site gave up a 4th-century BC signet-ring bearing the name of Dedatos, probably a local ruler. The city''s ancient name is unknown."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-028 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Vani stands on a hill [S1]; it lies in ancient Colchis [S2]; a signet-ring was found at the site [S5]; the signet-ring dates to the 4th century BC [S5]; the ring bears the name Dedatos [S5]; Dedatos was probably a local ruler [S5]; the ancient name of the city is unknown [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-083 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Vani Archaeological Site is the site of an ancient city (a vibrant urban settlement) [SUPPORTED: https://en.wikipedia.org/wiki/Vani_archaeological_site]; The site lies in ancient Colchis [SUPPORTED: https://en.wikipedia.org/wiki/Vani_archaeological_site]; The site is on a hill [SUPPORTED: https://en.wikipedia.org/wiki/Vani_archaeological_site]; A signet-ring dated to the 4th century BC was found at Vani [SUPPORTED: https://en.wikipedia.org/wiki/Vani_archaeological_site]; The signet-ring bears the name of Dedatos [SUPPORTED: https://en.wikipedia.org/wiki/Vani_archaeological_site]; Dedatos was probably a local ruler [SUPPORTED: https://en.wikipedia.org/wiki/Vani_archaeological_site]; The city''s ancient name is unknown [SUPPORTED: https://en.wikipedia.org/wiki/Vani_archaeological_site]"}]'::jsonb),
    ('e9e6da5f-9c61-444a-aa39-6a2a690813b7'::uuid, 'card_description', 'Kʼatepan translates as old church. Two large terraces set against a mountainside stand behind its plaza, where the Maya temple''s collapsed corner reveals finely cut stonework beneath.', 'A small Postclassic Maya plaza from 950-1539 AD, set against a mountainside with broad stairways. Nineteen structures cluster in six architectural groups.', 'teaser-card-s016-rollback:e9e6da5f-9c61-444a-aa39-6a2a690813b7:card_description', 'rollback of teaser-card-s016: card_description ''A small Postclassic Maya plaza from 950-1539 AD, set against a mountainside with broad stairways. Nineteen structures cluster in six architectural groups.'' restored on Kʼatepan', 'ab9487cbd9388fdb600b78ab97be0dd4bf09d4b839ebf4b54857298bf04a7cad|a6649e77bef62e56de685fa76a291b3c78057e9d89535d82325fee710b304af4|a6649e77bef62e56de685fa76a291b3c78057e9d89535d82325fee710b304af4', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-028", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Kʼatepan translates as old church. Two large terraces set against a mountainside stand behind its plaza, where the Maya temple''s collapsed corner reveals finely cut stonework beneath."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-028 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the name Kʼatepan translates as old church [S2]; the site has two large terraces [S3]; the terraces are set against a mountainside [S3]; the terraces stand behind the plaza (the plaza lies in front of them) [S3]; the site is Maya [S1]; the temple stands in the plaza [S7]; a corner of the temple has collapsed [S8]; the collapse reveals finely cut stonework beneath (a substructure) [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-083 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Kʼatepan is an archaeological site of the ancient Maya civilization (Guatemala) [SUPPORTED: https://en.wikipedia.org/wiki/K%CA%BCatepan]; The name Kʼatepan translates as old church [SUPPORTED: https://en.wikipedia.org/wiki/K%CA%BCatepan]; The site has two large terraces [SUPPORTED: https://en.wikipedia.org/wiki/K%CA%BCatepan]; The terraces are set against a mountainside [SUPPORTED: https://en.wikipedia.org/wiki/K%CA%BCatepan]; The terraces stand behind the plaza (the plaza lies in front of them) [SUPPORTED: https://en.wikipedia.org/wiki/K%CA%BCatepan]; A Maya temple stands in the plaza [SUPPORTED: https://en.wikipedia.org/wiki/K%CA%BCatepan]; A corner of the temple has collapsed [SUPPORTED: https://en.wikipedia.org/wiki/K%CA%BCatepan]; The collapsed corner reveals stonework beneath (a substructure) [SUPPORTED: https://en.wikipedia.org/wiki/K%CA%BCatepan]; The stonework revealed beneath is finely cut [SUPPORTED: https://en.wikipedia.org/wiki/K%CA%BCatepan]"}]'::jsonb),
    ('ea13709c-21ca-4d9b-9ccf-578e07e1c2ca'::uuid, 'card_description', 'Crikvenica grew over Ad Turres, a Roman settlement and military base. At Igralište, a Roman workshop made amphorae and pottery from the late 1st century BC to the end of the 2nd century AD.', 'A Roman-era settlement and ceramic workshop. Stamped maker''s marks on the pottery identify pieces from this specific workshop traded across the Adriatic.', 'teaser-card-s016-rollback:ea13709c-21ca-4d9b-9ccf-578e07e1c2ca:card_description', 'rollback of teaser-card-s016: card_description "A Roman-era settlement and ceramic workshop. Stamped maker''s marks on the pottery identify pieces from this specific workshop traded across the Adriatic." restored on Crikvenica', '6fa09052618e941e5f91b876d119023179f32a6a720bee21d6682cd8fa883f6a|6dafbde98831d9b5929479fef4ff2167b94bcf7df69a15e1aeb97292a91f38c0|6dafbde98831d9b5929479fef4ff2167b94bcf7df69a15e1aeb97292a91f38c0', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-028", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Crikvenica grew over Ad Turres, a Roman settlement and military base. At Igralište, a Roman workshop made amphorae and pottery from the late 1st century BC to the end of the 2nd century AD."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-028 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Crikvenica grew on the site of Ad Turres [S1]; Ad Turres was a Roman settlement [S1]; Ad Turres was a military base [S1]; a workshop was at Igralište [S2]; the workshop was Roman [S2, S3]; it made amphorae and pottery [S3]; it operated from the late 1st century BC [S3]; it operated until the end of the 2nd century AD [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-083 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Crikvenica (a town in Croatia) was developed over the Roman settlement Ad Turres [SUPPORTED: https://en.wikipedia.org/wiki/Crikvenica]; Ad Turres was a Roman settlement [SUPPORTED: https://en.wikipedia.org/wiki/Crikvenica]; Ad Turres was also a military base [SUPPORTED: https://en.wikipedia.org/wiki/Crikvenica]; At Igralište (an archaeological site at Crikvenica) there was a Roman workshop [SUPPORTED: https://en.wikipedia.org/wiki/Crikvenica]; The workshop made amphorae [SUPPORTED: https://en.wikipedia.org/wiki/Crikvenica]; The workshop made pottery [SUPPORTED: https://en.wikipedia.org/wiki/Crikvenica]; The workshop began in the late 1st century BC [SUPPORTED: https://en.wikipedia.org/wiki/Crikvenica]; The workshop ran until the end of the 2nd century AD [SUPPORTED: https://en.wikipedia.org/wiki/Crikvenica]"}]'::jsonb),
    ('eb379653-acb9-464d-af06-a0c15a7d6304'::uuid, 'card_description', 'Epidaurum was destroyed by Avars and Slavic invaders in the 7th century. Its refugees fled to the nearby island of Laas, from which Ragusa was founded, in time to become Dubrovnik.', 'Founded 6th century BC as a Greek colony, renamed Epidaurum under Rome in 228 BC. Now Cavtat, 15 km south of Dubrovnik; besieged in Caesar''s civil war but saved by consul Publius Vatinius.', 'teaser-card-s016-rollback:eb379653-acb9-464d-af06-a0c15a7d6304:card_description', 'rollback of teaser-card-s016: card_description "Founded 6th century BC as a Greek colony, renamed Epidaurum under Rome in 228 BC. Now Cavtat, 15 km south of Dubrovnik; besieged in Caesar''s civil war but saved by consul Publius Vatinius." restored on Epidaurum', '40ab1fd6e6c89d21834d7a4881f39f4cd982f993863265af986fdce82ce2ea0a|29b5fd1bba6e8b7ff3c9d2657ec228c2aac6b9354ba6d8e4ae457b3126ec3dd8|29b5fd1bba6e8b7ff3c9d2657ec228c2aac6b9354ba6d8e4ae457b3126ec3dd8', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-028", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Epidaurum was destroyed by Avars and Slavic invaders in the 7th century. Its refugees fled to the nearby island of Laas, from which Ragusa was founded, in time to become Dubrovnik."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-028 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Epidaurum was destroyed by Avars and Slavic invaders [S4]; the destruction was in the 7th century [S4]; its refugees fled to the nearby island of Laas [S5]; Ragusa was founded from Laas [S5]; Ragusa in time became Dubrovnik [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-083 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Epidaurum was an ancient city (a Greek colony renamed under Roman rule, near present-day Cavtat, Croatia) [SUPPORTED: https://en.wikipedia.org/wiki/Epidaurum]; Epidaurum was destroyed by Avars and Slavic invaders [SUPPORTED: https://en.wikipedia.org/wiki/Epidaurum]; The destruction happened in the 7th century [SUPPORTED: https://en.wikipedia.org/wiki/Epidaurum]; Refugees of Epidaurum fled after the destruction [SUPPORTED: https://en.wikipedia.org/wiki/Epidaurum]; The refugees fled to the nearby island of Laas [SUPPORTED: https://en.wikipedia.org/wiki/Epidaurum]; Ragusa was founded from the island of Laas [SUPPORTED: https://en.wikipedia.org/wiki/Epidaurum]; Ragusa in time became Dubrovnik [SUPPORTED: https://en.wikipedia.org/wiki/Epidaurum]"}]'::jsonb),
    ('eb482c92-0104-4243-8ae6-0316f0bdec37'::uuid, 'card_description', 'The Dimini area holds a Neolithic settlement and a Mycenean one. Dimini culture is well known for abstract painted vessels; Dimini ware has been identified as far away as Cakran in Albania.', 'The Neolithic settlement in Dimini was discovered near the end of the 19th century and was first excavated by the archaeologists Christos Tsountas and Valerios Stais.', 'teaser-card-s016-rollback:eb482c92-0104-4243-8ae6-0316f0bdec37:card_description', 'rollback of teaser-card-s016: card_description ''The Neolithic settlement in Dimini was discovered near the end of the 19th century and was first excavated by the archaeologists Christos Tsountas and Valerios Stais.'' restored on Dimini', '2c4d115141a2b33ba1616fdfbd027646d79841c941dd77dbdd231c4089c3d96e|0acd855960c4c2ab265808d386b176cffc91e4b3915253117795fcca0ebc7adf|0acd855960c4c2ab265808d386b176cffc91e4b3915253117795fcca0ebc7adf', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-rewrite1-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Dimini area holds a Neolithic settlement and a Mycenean one. Dimini culture is well known for abstract painted vessels; Dimini ware has been identified as far away as Cakran in Albania."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check1-002 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the Dimini area holds a Neolithic settlement [S1]; the Dimini area holds a Mycenean settlement [S1]; Dimini culture is well known for its painted vessels [S3]; the painted vessels are abstract [S3]; Dimini ware has been identified as far away as Cakran [S4]; Cakran is in Albania [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-084 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Dimini is a settlement area (a village near Volos) whose area contains settlements: a Neolithic one and a Mycenean one (central claim) [SUPPORTED: https://en.wikipedia.org/wiki/Dimini]; The Dimini area holds a Neolithic settlement [SUPPORTED: https://en.wikipedia.org/wiki/Dimini]; The Dimini area holds a Mycenean settlement [SUPPORTED: https://en.wikipedia.org/wiki/Dimini]; Dimini is in Greece [SUPPORTED: https://en.wikipedia.org/wiki/Dimini]; Dimini culture is well known for abstract painted vessels [SUPPORTED: https://en.wikipedia.org/wiki/Dimini]; Dimini ware has been identified as far away as Cakran [SUPPORTED: https://en.wikipedia.org/wiki/Dimini]; Cakran, where Dimini ware was found, is in Albania [SUPPORTED: https://en.wikipedia.org/wiki/Dimini]"}]'::jsonb),
    ('eb752f57-8327-43bc-b6c4-98fa1f0a7ac2'::uuid, 'card_description', 'From around 3000 BC, the Hartberg Megalithic Tomb held bones and a small beaker that suggests use, perhaps with interruptions, for around 1,000 years. Iron Age builders took its slabs.', 'The only Neolithic gallery grave of its type in the entire region, dating to about 3000 BC. Two sandstone-slab chambers were built into the slope of the Hartberg.', 'teaser-card-s016-rollback:eb752f57-8327-43bc-b6c4-98fa1f0a7ac2:card_description', 'rollback of teaser-card-s016: card_description ''The only Neolithic gallery grave of its type in the entire region, dating to about 3000 BC. Two sandstone-slab chambers were built into the slope of the Hartberg.'' restored on Hartberg Megalithic Tomb', '550b8b7e0b8dd7e0d67d906d822cb441e453ddd99778a3ab760554d13bbe0f71|25531a452e397149b477cb3c3c180bd840fd6605b26871df4349a80c0160b4af|25531a452e397149b477cb3c3c180bd840fd6605b26871df4349a80c0160b4af', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-028", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "From around 3000 BC, the Hartberg Megalithic Tomb held bones and a small beaker that suggests use, perhaps with interruptions, for around 1,000 years. Iron Age builders took its slabs."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-028 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the tomb dates from around 3000 BC [S2, S3]; bones were found in the tomb [S3]; a small beaker was found in the tomb [S4]; the beaker suggests the site was in use for around 1,000 years [S4]; the use was perhaps with interruptions [S4]; in the Iron Age builders took slabs of the tomb [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-084 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Hartberg Megalithic Tomb is a megalithic tomb (a Neolithic gallery grave) in Germany (central claim) [SUPPORTED: https://en.wikipedia.org/wiki/Hartberg_megalithic_tomb]; The tomb is in Germany (Rhineland-Palatinate) [SUPPORTED: https://en.wikipedia.org/wiki/Hartberg_megalithic_tomb]; The site dates from around 3000 BC [SUPPORTED: https://en.wikipedia.org/wiki/Hartberg_megalithic_tomb]; The tomb held bones [SUPPORTED: https://en.wikipedia.org/wiki/Hartberg_megalithic_tomb]; The tomb held a small beaker [SUPPORTED: https://en.wikipedia.org/wiki/Hartberg_megalithic_tomb]; The beaker suggests the site was in use, perhaps with interruptions, for around 1,000 years [SUPPORTED: https://en.wikipedia.org/wiki/Hartberg_megalithic_tomb]; Iron Age builders took slabs from the tomb [SUPPORTED: https://en.wikipedia.org/wiki/Hartberg_megalithic_tomb]"}]'::jsonb),
    ('ec987c81-f12a-429d-b312-7bd15d98412c'::uuid, 'card_description', 'In the Puuc region, the Maya city of Uxmal raises its Pyramid of the Magician in five oval levels, unusual among Maya structures, amid buildings noted for their size and decoration.', 'The buildings take advantage of the terrain to gain height and acquire important volumes, including the Pyramid of the Magician, with five levels, and the Governor''s Palace.', 'teaser-card-s016-rollback:ec987c81-f12a-429d-b312-7bd15d98412c:card_description', 'rollback of teaser-card-s016: card_description "The buildings take advantage of the terrain to gain height and acquire important volumes, including the Pyramid of the Magician, with five levels, and the Governor''s Palace." restored on Uxmal', 'd4135c5ee62a9856c51122dad516f53fc68c71e94d6f40482d3273e9482b2583|10a865444304e700ed978ffa9931bec994c6f7882763ca848db194c2312cfa27|10a865444304e700ed978ffa9931bec994c6f7882763ca848db194c2312cfa27', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-028", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "In the Puuc region, the Maya city of Uxmal raises its Pyramid of the Magician in five oval levels, unusual among Maya structures, amid buildings noted for their size and decoration."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-028 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Uxmal is in the Puuc region [S3]; Uxmal is a Maya city [S1]; Uxmal has a Pyramid of the Magician [S7, S8]; the pyramid has five levels [S7]; the levels are oval in outline [S8]; this is unusual among Maya structures [S8]; Uxmal''s buildings are noted for their size and decoration [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-084 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote