    ('eecda91b-c255-4362-a7ed-1beac2c13869'::uuid, 'card_description', 'In Newport, Pembrokeshire, a 4-metre-long capstone rests on smaller rocks: Carreg Coetan Arthur, a Neolithic burial chamber from around 3000 BC that would once have been earth covered.', 'Carreg Coetan Arthur dates from around 3000 BC and is the remains of a Neolithic burial chamber.', 'teaser-card-s016-rollback:eecda91b-c255-4362-a7ed-1beac2c13869:card_description', 'rollback of teaser-card-s016: card_description ''Carreg Coetan Arthur dates from around 3000 BC and is the remains of a Neolithic burial chamber.'' restored on Carreg Coetan Arthur', '8b158d66d2122c1ec9f5c0f74c31976bc74e5c4f8ca9addcfc1d220a6e78d796|2a3d253ee4fbfceb6c905681ba917196600ff0e259f257c972a4fa34a01d4d04|2a3d253ee4fbfceb6c905681ba917196600ff0e259f257c972a4fa34a01d4d04', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-028", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "In Newport, Pembrokeshire, a 4-metre-long capstone rests on smaller rocks: Carreg Coetan Arthur, a Neolithic burial chamber from around 3000 BC that would once have been earth covered."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-028 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the site is in Newport, Pembrokeshire [S1]; a 4-metre-long capstone rests on smaller rocks [S3]; it is a Neolithic burial chamber [S1, S2]; it dates from around 3000 BC [S2]; it would originally have been earth covered [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-084 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Carreg Coetan Arthur is a Neolithic dolmen in Newport, Pembrokeshire, Wales (central claim) [SUPPORTED: https://en.wikipedia.org/wiki/Carreg_Coetan_Arthur]; It is a Neolithic burial chamber [SUPPORTED: https://en.wikipedia.org/wiki/Carreg_Coetan_Arthur]; It dates from around 3000 BC [SUPPORTED: https://en.wikipedia.org/wiki/Carreg_Coetan_Arthur]; A 4-metre-long capstone rests on smaller rocks [SUPPORTED: https://en.wikipedia.org/wiki/Carreg_Coetan_Arthur]; The chamber would once have been earth covered [SUPPORTED: https://en.wikipedia.org/wiki/Carreg_Coetan_Arthur]"}]'::jsonb),
    ('efe2bc83-83cc-4393-b725-a18543dc9d5f'::uuid, 'card_description', NULL, 'The Antequera Dolmens Site is a cultural heritage ensemble comprising three cultural monuments and 2 natural mountain features in and near the city of Antequera in Andalusia.', 'teaser-card-s016-rollback:efe2bc83-83cc-4393-b725-a18543dc9d5f:card_description', 'rollback of teaser-card-s016: card_description ''The Antequera Dolmens Site is a cultural heritage ensemble comprising three cultural monuments and 2 natural mountain features in and near the city of Antequera in Andalusia.'' restored on Antequera Dolmens Site', '||c61e6f567b29dd8de8e9948b8549d6294990b679ed24eed79c054a6d7049ebb6', '[{"source": "lane WB run wb-ws-2026-09-27-01: unproven-after-verify", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The web check could not prove: The Antequera Dolmens Site is an ensemble of megalithic monuments (the Dolmen of Menga, the Dolmen of Viera and the Tholos of El Romeral) (central claim); The web check could not prove: The Antequera Dolmens Site is a megalithic monument ensemble (dolmens and a tholos) in Antequera, Spain (central claim: what kind of place and where); The web check could not prove: The Dolmen of Menga is one of the dolmens of the site"}]'::jsonb),
    ('eff62515-9b70-43cc-afe6-c803dd4b5bc3'::uuid, 'card_description', 'On the edge of the Western Desert, the Giza Necropolis holds the Great Pyramid, the pyramids of Khafre and Menkaure, temples, cemeteries, a workers'' village and the Great Sphinx.', 'The site is at the edge of the Western Desert, approximately 9 km west of the Nile River in the city of Giza, and about 13 km southwest of the city centre of Cairo.', 'teaser-card-s016-rollback:eff62515-9b70-43cc-afe6-c803dd4b5bc3:card_description', 'rollback of teaser-card-s016: card_description ''The site is at the edge of the Western Desert, approximately 9 km west of the Nile River in the city of Giza, and about 13 km southwest of the city centre of Cairo.'' restored on Giza Necropolis', 'e35ce8467348dcaab2c55e7dde46caeb452a734bdc44299d86415d43a52863e5|11849d64ac114bbea2a3426ad13009663bddb13747291b0842d3ac68fcbc021b|11849d64ac114bbea2a3426ad13009663bddb13747291b0842d3ac68fcbc021b', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-029", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "On the edge of the Western Desert, the Giza Necropolis holds the Great Pyramid, the pyramids of Khafre and Menkaure, temples, cemeteries, a workers'' village and the Great Sphinx."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-029 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the site lies on the edge of the Western Desert [S4]; the site holds the Great Pyramid [S1]; the site holds the pyramids of Khafre and Menkaure [S1]; the site includes temples [S3]; the site includes cemeteries [S3]; the site includes a workers'' village [S3]; the site holds the Great Sphinx [S1]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-085 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Giza Necropolis is a necropolis / pyramid complex in Egypt [SUPPORTED: https://en.wikipedia.org/wiki/Giza_pyramid_complex]; It lies on the edge of the Western Desert [SUPPORTED: https://en.wikipedia.org/wiki/Giza_pyramid_complex]; It holds the Great Pyramid [SUPPORTED: https://en.wikipedia.org/wiki/Giza_pyramid_complex]; It holds the pyramid of Khafre [SUPPORTED: https://en.wikipedia.org/wiki/Giza_pyramid_complex]; It holds the pyramid of Menkaure [SUPPORTED: https://en.wikipedia.org/wiki/Giza_pyramid_complex]; It includes temples [SUPPORTED: https://en.wikipedia.org/wiki/Giza_pyramid_complex]; It includes cemeteries [SUPPORTED: https://en.wikipedia.org/wiki/Giza_pyramid_complex]; It includes a workers'' village [SUPPORTED: https://en.wikipedia.org/wiki/Giza_pyramid_complex]; It holds the Great Sphinx [SUPPORTED: https://en.wikipedia.org/wiki/Giza_pyramid_complex]"}]'::jsonb),
    ('f04199e9-626c-4eda-bccf-0395ef21d332'::uuid, 'card_description', 'Near Koblenz, the ancient earthworks of the Goloring draw a circle in the land: a ditch 175 metres in diameter, about 80 cm deep, its outside embankment extending to 190 metres.', 'A Bronze Age earthwork 175 metres across from the Urnfield culture (1200–800 BC). It is linked to a widespread solar cult that gripped Central Europe during this period.', 'teaser-card-s016-rollback:f04199e9-626c-4eda-bccf-0395ef21d332:card_description', 'rollback of teaser-card-s016: card_description ''A Bronze Age earthwork 175 metres across from the Urnfield culture (1200–800 BC). It is linked to a widespread solar cult that gripped Central Europe during this period.'' restored on Goloring', '36834fc31272e8447769541dab30c33e8f45679651e426d17d65e0a6a659e2c3|545f7925db44bf2b9fe42de0f3e122ec4cc4f72879465656e7f954646405b887|545f7925db44bf2b9fe42de0f3e122ec4cc4f72879465656e7f954646405b887', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-029", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Near Koblenz, the ancient earthworks of the Goloring draw a circle in the land: a ditch 175 metres in diameter, about 80 cm deep, its outside embankment extending to 190 metres."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-029 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the Goloring is near Koblenz [S1]; the Goloring is an ancient earthworks monument [S1]; the earthwork forms a circle (a circular ditch) [S2]; the ditch is 175 metres in diameter [S2]; the ditch is about 80 cm deep [S4]; the outside embankment extends to 190 metres [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-085 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Goloring is an earthworks monument (a circular ditch-and-bank enclosure) [SUPPORTED: https://en.wikipedia.org/wiki/Goloring]; It is near Koblenz (Germany) [SUPPORTED: https://en.wikipedia.org/wiki/Goloring]; The earthworks are ancient [SUPPORTED: https://en.wikipedia.org/wiki/Goloring]; It has a circular ditch 175 metres in diameter [SUPPORTED: https://en.wikipedia.org/wiki/Goloring]; Its outside embankment extends to 190 metres [SUPPORTED: https://en.wikipedia.org/wiki/Goloring]; The ditch is about 80 cm deep [SUPPORTED: https://en.wikipedia.org/wiki/Goloring]"}]'::jsonb),
    ('f0e4bbe8-a16f-46af-a1fe-0ba46a127c89'::uuid, 'card_description', 'Where the Ceyhan breaks through the Misis Mountains rises Sirkeli Höyüğü, one of the largest settlement mounds of Cilicia, spread over approximately 80 ha, 40 kilometers east of Adana.', 'Sirkeli Höyük is one of the largest tells of Cilicia with an area of approximately 80 ha.', 'teaser-card-s016-rollback:f0e4bbe8-a16f-46af-a1fe-0ba46a127c89:card_description', 'rollback of teaser-card-s016: card_description ''Sirkeli Höyük is one of the largest tells of Cilicia with an area of approximately 80 ha.'' restored on Sirkeli Höyüğü', 'a41c603638a0051ff70364b930686d33328b98f59e04174197ea5ae7c99b4f25|c787948581f0d65d6e83bcdc630b2f4f9a5e8389e67c789c7e8d7f0e250a5a2f|c787948581f0d65d6e83bcdc630b2f4f9a5e8389e67c789c7e8d7f0e250a5a2f', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-029", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Where the Ceyhan breaks through the Misis Mountains rises Sirkeli Höyüğü, one of the largest settlement mounds of Cilicia, spread over approximately 80 ha, 40 kilometers east of Adana."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-029 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Sirkeli Höyüğü lies where the Ceyhan breaks through the Misis Mountains [S2]; Sirkeli Höyüğü is a settlement mound (tell) [S1]; it is one of the largest settlement mounds of Cilicia [S1]; it covers approximately 80 ha [S1]; it is 40 kilometers east of Adana [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-085 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Sirkeli Höyük is a settlement mound (tell) in Cilicia [SUPPORTED: https://en.wikipedia.org/wiki/Sirkeli_H%C3%B6y%C3%BCk]; It lies where the Ceyhan breaks through the Misis Mountains [SUPPORTED: https://www.sirkeli.ch/de/projekt/ergebnisse/]; It is one of the largest settlement mounds of Cilicia [SUPPORTED: https://en.wikipedia.org/wiki/Sirkeli_H%C3%B6y%C3%BCk]; It covers approximately 80 ha [SUPPORTED: https://en.wikipedia.org/wiki/Sirkeli_H%C3%B6y%C3%BCk]; It is 40 kilometers east of Adana [SUPPORTED: https://en.wikipedia.org/wiki/Sirkeli_H%C3%B6y%C3%BCk]"}]'::jsonb),
    ('f281f0f2-0912-4870-b2d9-f58aa283c9a3'::uuid, 'card_description', 'Layers of time at Desborough Castle: a Norman ringwork partly over a mound, possibly a barrow reused as a Saxon moot, both inside a square enclosure, possibly Iron Age or Late Bronze Age.', 'Three eras of fortification stack on one Buckinghamshire hilltop: an Iron Age enclosure, a Saxon moot mound, and a Norman ringwork partly overlying the earlier structures.', 'teaser-card-s016-rollback:f281f0f2-0912-4870-b2d9-f58aa283c9a3:card_description', 'rollback of teaser-card-s016: card_description ''Three eras of fortification stack on one Buckinghamshire hilltop: an Iron Age enclosure, a Saxon moot mound, and a Norman ringwork partly overlying the earlier structures.'' restored on Desborough Castle', '2981f53cfc7fd70fb2241a75791dd9fe5af4e489f232d369e267edfd49dcb8c9|440381de03ef476b9d46ca4f84698bb5498b57d513389b56b6f22a5f4882d904|440381de03ef476b9d46ca4f84698bb5498b57d513389b56b6f22a5f4882d904', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-029", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Layers of time at Desborough Castle: a Norman ringwork partly over a mound, possibly a barrow reused as a Saxon moot, both inside a square enclosure, possibly Iron Age or Late Bronze Age."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-029 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the site shows layers of several periods overlapping (ringwork over a mound inside an enclosure) [S1, S2]; Desborough Castle has a Norman ringwork [S1]; the ringwork partly overlies a mound [S1]; the mound is possibly a barrow reused as a Saxon moot [S1]; the ringwork and mound lie inside a square enclosure [S2]; the enclosure is possibly Iron Age or Late Bronze Age [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-085 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Desborough Castle is a multi-period earthwork site whose main feature is a Norman ringwork (a castle) [SUPPORTED: https://heritageportal.buckinghamshire.gov.uk/Monument/MBC55]; The site has a Norman ringwork [SUPPORTED: https://heritageportal.buckinghamshire.gov.uk/Monument/MBC55]; The Norman ringwork lies partly over a mound [SUPPORTED: https://en.wikipedia.org/wiki/Desborough_Castle]; The mound is possibly a barrow [SUPPORTED: https://heritageportal.buckinghamshire.gov.uk/Monument/MBC55]; The barrow was possibly reused as a Saxon moot [SUPPORTED: https://heritageportal.buckinghamshire.gov.uk/Monument/MBC55]; Both ringwork and mound lie inside a square enclosure [SUPPORTED: https://en.wikipedia.org/wiki/Desborough_Castle]; The enclosure is possibly Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Desborough_Castle]; The enclosure is possibly Late Bronze Age [SUPPORTED: https://heritageportal.buckinghamshire.gov.uk/Monument/MBC55]"}]'::jsonb),
    ('f29afd0d-6fb8-4405-bee8-c1b17a6989e3'::uuid, 'card_description', 'On the New River, halfway between Cerros and Lamanai, lies San Estevan, a Maya regional political center from the Late Formative on, where Mound XV still rises 15 m, the highest remaining.', 'Maya site occupied 800 BC–900 AD, spanning Formative and Classic eras. One of the earliest settlements in the region, 1 km from the modern community that shares its name.', 'teaser-card-s016-rollback:f29afd0d-6fb8-4405-bee8-c1b17a6989e3:card_description', 'rollback of teaser-card-s016: card_description ''Maya site occupied 800 BC–900 AD, spanning Formative and Classic eras. One of the earliest settlements in the region, 1 km from the modern community that shares its name.'' restored on San Estevan', 'efe6aa986631e58d8dc49fef0008a02b8ec8029464ce53a9b6ac66b21c0d2857|ba125b1239c5b8b294c0e2d67d0d0a75431d040b41254f9ab4a75a51f42ef062|ba125b1239c5b8b294c0e2d67d0d0a75431d040b41254f9ab4a75a51f42ef062', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-029", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "On the New River, halfway between Cerros and Lamanai, lies San Estevan, a Maya regional political center from the Late Formative on, where Mound XV still rises 15 m, the highest remaining."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-029 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "San Estevan lies on the New River [S3]; San Estevan lies halfway between Cerros and Lamanai [S3]; San Estevan is a Maya site [S2]; San Estevan was a regional political center from the Late Formative period on [S4]; Mound XV rises 15 m [S7]; Mound XV is the highest structure remaining at the site [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-085 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "San Estevan is a Maya archaeological site in northern Belize [SUPPORTED: https://en.wikipedia.org/wiki/San_Estevan_(Maya_site)]; San Estevan lies on the New River [SUPPORTED: https://en.wikipedia.org/wiki/San_Estevan_(Maya_site)]; It lies halfway between Cerros and Lamanai [SUPPORTED: https://en.wikipedia.org/wiki/San_Estevan_(Maya_site)]; It was a regional political center [SUPPORTED: https://en.wikipedia.org/wiki/San_Estevan_(Maya_site)]; It was a regional political center from the Late Formative on [SUPPORTED: https://en.wikipedia.org/wiki/San_Estevan_(Maya_site)]; Mound XV still rises 15 m [SUPPORTED: https://en.wikipedia.org/wiki/San_Estevan_(Maya_site)]; Mound XV is the highest structure remaining at the site [SUPPORTED: https://en.wikipedia.org/wiki/San_Estevan_(Maya_site)]"}]'::jsonb),
    ('f4e3fdef-07f1-4327-b0db-c01c671bfafc'::uuid, 'card_description', 'At the foot of Slieve Gullion, the granite capstone of Ballykeel Dolmen balances on the tips of three portal stones. Its chamber held three highly decorated Ballyalton bowls.', 'The dolmen sits at the southern end of a large cairn, of approximately 30x10 metres, the north end of which also contains a cist.', 'teaser-card-s016-rollback:f4e3fdef-07f1-4327-b0db-c01c671bfafc:card_description', 'rollback of teaser-card-s016: card_description ''The dolmen sits at the southern end of a large cairn, of approximately 30x10 metres, the north end of which also contains a cist.'' restored on Ballykeel Dolmen', '416e1b7998114a18313e8694d052817396f810a66e9ab2acb88d73ebcca52f22|1a8b6da3245544a0791d67eaafb50a933cca07839d45a41a3e461d3c66c7ce82|1a8b6da3245544a0791d67eaafb50a933cca07839d45a41a3e461d3c66c7ce82', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-029", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "At the foot of Slieve Gullion, the granite capstone of Ballykeel Dolmen balances on the tips of three portal stones. Its chamber held three highly decorated Ballyalton bowls."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-029 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Ballykeel Dolmen stands at the foot of Slieve Gullion [S1]; its capstone is granite [S5]; the capstone balances on the tips of three portal stones [S5]; the chamber held three highly decorated Ballyalton bowls [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-086 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Ballykeel Dolmen is a dolmen, a Neolithic tripod portal tomb, at the foot of Slieve Gullion in Northern Ireland [SUPPORTED: https://en.wikipedia.org/wiki/Ballykeel_Dolmen]; The site lies at the foot of Slieve Gullion [SUPPORTED: https://en.wikipedia.org/wiki/Ballykeel_Dolmen]; The capstone is of granite [SUPPORTED: https://en.wikipedia.org/wiki/Ballykeel_Dolmen]; The capstone balances on the tips of three portal stones [SUPPORTED: https://en.wikipedia.org/wiki/Ballykeel_Dolmen]; The chamber held three highly decorated Ballyalton bowls [SUPPORTED: https://en.wikipedia.org/wiki/Ballykeel_Dolmen]"}]'::jsonb),
    ('f524b8bf-c69d-4dd3-8fb6-549de566d297'::uuid, 'card_description', 'On the slopes of Blue Bell Hill in Kent, the White Horse Stone took on the name and folklore of a second stone destroyed before 1834. Near it, excavators found an Early Neolithic longhouse.', 'The Lower White Horse Stone was destroyed prior to 1834, at which time the surviving Upper White Horse Stone took on its name and folkloric associations.', 'teaser-card-s016-rollback:f524b8bf-c69d-4dd3-8fb6-549de566d297:card_description', 'rollback of teaser-card-s016: card_description ''The Lower White Horse Stone was destroyed prior to 1834, at which time the surviving Upper White Horse Stone took on its name and folkloric associations.'' restored on White Horse Stone', '7b41216f48593ae05b27e14616e27f1e0e86a1d3dc688eca6e34f91b67e9f772|d4bb79eb720dfb4463a199d90f19e2df201740cb4f3fd44e98f490b9d83cd6fe|d4bb79eb720dfb4463a199d90f19e2df201740cb4f3fd44e98f490b9d83cd6fe', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-rewrite-v-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "On the slopes of Blue Bell Hill in Kent, the White Horse Stone took on the name and folklore of a second stone destroyed before 1834. Near it, excavators found an Early Neolithic longhouse."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-v-003 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the White Horse Stone is on the slopes of Blue Bell Hill [S1]; Blue Bell Hill is in Kent [S1]; a second stone (the Lower White Horse Stone) was destroyed before 1834 [S2]; the surviving White Horse Stone took on the name of the destroyed stone [S2]; the surviving stone took on the folklore of the destroyed stone [S2]; excavators found a longhouse near the stone [S4]; the longhouse is Early Neolithic [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify2-007 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The White Horse Stone is a sarsen megalith (central claim: what kind of place it is) [SUPPORTED: https://en.wikipedia.org/wiki/White_Horse_Stone]; It stands on the slopes of Blue Bell Hill [SUPPORTED: https://en.wikipedia.org/wiki/White_Horse_Stone]; Blue Bell Hill is in Kent [SUPPORTED: https://en.wikipedia.org/wiki/White_Horse_Stone]; A second stone, destroyed before 1834, existed [SUPPORTED: https://en.wikipedia.org/wiki/White_Horse_Stone]; The surviving stone took on the name of the destroyed second stone [SUPPORTED: https://en.wikipedia.org/wiki/White_Horse_Stone]; The surviving stone took on the folklore of the destroyed second stone [SUPPORTED: https://en.wikipedia.org/wiki/White_Horse_Stone]; Excavators found a longhouse near the stone [SUPPORTED: https://en.wikipedia.org/wiki/White_Horse_Stone]; The longhouse dates to the Early Neolithic [SUPPORTED: https://en.wikipedia.org/wiki/White_Horse_Stone]"}]'::jsonb),
    ('f5893102-13b9-44a0-bc87-8348f7da115c'::uuid, 'card_description', 'On a hill spur near Kronach, the Heunischenburg is the oldest known and investigated stone fortification north of the Alps. Its sandstone wall probably burned down during a battle.', 'The oldest known stone fortification north of the Alps, dating to the 9th century BC. It guarded a Bronze Age copper and tin trade route through the mountains.', 'teaser-card-s016-rollback:f5893102-13b9-44a0-bc87-8348f7da115c:card_description', 'rollback of teaser-card-s016: card_description ''The oldest known stone fortification north of the Alps, dating to the 9th century BC. It guarded a Bronze Age copper and tin trade route through the mountains.'' restored on Heunischenburg', '938263b81e034db634d94a0df00aace544645dffff67056c9695455b69805d03|7fa771513c077de359f3d555cc334b3460d0fb341cb1d543a1998d826f121d12|7fa771513c077de359f3d555cc334b3460d0fb341cb1d543a1998d826f121d12', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-029", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "On a hill spur near Kronach, the Heunischenburg is the oldest known and investigated stone fortification north of the Alps. Its sandstone wall probably burned down during a battle."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-029 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the Heunischenburg lies on a hill spur [S3]; it is near Kronach [S1]; it is the oldest known and archaeologically investigated stone fortification north of the Alps [S2]; its sandstone wall probably burned down during a battle [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-086 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Heunischenburg is a stone fortification near the town of Kronach in Germany [SUPPORTED: https://en.wikipedia.org/wiki/Heunischenburg]; The fort lies on a hill spur [SUPPORTED: https://en.wikipedia.org/wiki/Heunischenburg]; It is the oldest known and archaeologically investigated stone fortification north of the Alps [SUPPORTED: https://en.wikipedia.org/wiki/Heunischenburg]; Its wall was of sandstone [SUPPORTED: https://en.wikipedia.org/wiki/Heunischenburg]; The sandstone wall probably burned down during a battle [SUPPORTED: https://en.wikipedia.org/wiki/Heunischenburg]"}]'::jsonb),
    ('f5e7956b-9aa4-47b0-b88a-3ed159f451d1'::uuid, 'card_description', 'Llansteffan Castle rests within the earthwork rings of a much older Iron Age promontory fort. The original earthworks can still be seen, and were used as part of its defence system.', 'The castle sits on a much older Iron Age promontory fort, proving Llansteffan has been inhabited for several millennia.', 'teaser-card-s016-rollback:f5e7956b-9aa4-47b0-b88a-3ed159f451d1:card_description', 'rollback of teaser-card-s016: card_description ''The castle sits on a much older Iron Age promontory fort, proving Llansteffan has been inhabited for several millennia.'' restored on Llansteffan Castle', '8c5b8877bfc7a2e3cf8f0efcab44c890fcd42075ee3ecf3683ef4b9828e5f7c7|da412ce025e9314ef9fcf00b116c7ddf48923223674bde225ef6adc9385a9e9b|da412ce025e9314ef9fcf00b116c7ddf48923223674bde225ef6adc9385a9e9b', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-rewrite-v-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Llansteffan Castle rests within the earthwork rings of a much older Iron Age promontory fort. The original earthworks can still be seen, and were used as part of its defence system."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-v-003 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the castle rests within the earthwork rings [S4]; the earthwork rings belong to an Iron Age promontory fort [S2, S4]; the fort is much older than the castle [S2]; the original earthworks can still be seen [S4]; the original earthworks were used as part of the castle''s defence system [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify2-008 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Llansteffan Castle is a castle in Llansteffan, Carmarthenshire, Wales (central claim: the site is a castle, in Wales) [SUPPORTED: https://en.wikipedia.org/wiki/Llansteffan_Castle]; The castle sits on a much older Iron Age promontory fort [SUPPORTED: https://en.wikipedia.org/wiki/Llansteffan_Castle]; The castle rests within the earthwork rings of that fort [SUPPORTED: https://en.wikipedia.org/wiki/Llansteffan_Castle]; The original earthworks can still be seen [SUPPORTED: https://en.wikipedia.org/wiki/Llansteffan_Castle]; The original earthworks were used as part of the castle''s defence system [SUPPORTED: https://en.wikipedia.org/wiki/Llansteffan_Castle]"}]'::jsonb),
    ('f6916087-0021-44fe-af7e-5111e67f660a'::uuid, 'card_description', 'Found around 1938 as a quarry began work, Risovača Cave held worked flint tools and bone artifacts in its sediments, attributed to Neanderthals at the end of the Middle Paleolithic.', 'Set 17 m above the Kubršnica river at the edge of Aranđelovac, this Paleolithic cave confirmed human occupation south of the Sava–Danube line. Its finds span tens of thousands of years.', 'teaser-card-s016-rollback:f6916087-0021-44fe-af7e-5111e67f660a:card_description', 'rollback of teaser-card-s016: card_description ''Set 17 m above the Kubršnica river at the edge of Aranđelovac, this Paleolithic cave confirmed human occupation south of the Sava–Danube line. Its finds span tens of thousands of years.'' restored on Risovača Cave', 'b13da2e4e571ea8cbe7f47e9ec6853e356ddfed0a3f97158580afa9da39d5247|13a167a57e54fd4c9f58f8df7204ffda81f173ebb891e9d9fab65cc64ddb240a|13a167a57e54fd4c9f58f8df7204ffda81f173ebb891e9d9fab65cc64ddb240a', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-029", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Found around 1938 as a quarry began work, Risovača Cave held worked flint tools and bone artifacts in its sediments, attributed to Neanderthals at the end of the Middle Paleolithic."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-029 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the cave was found around 1938 [S4]; it was found as a quarry began work (became operational) [S4]; the cave held worked flint tools [S6]; the cave held bone artifacts [S6]; the finds lay in its sediments [S6]; the finds are attributed to Neanderthals [S7]; the finds date to the end of the Middle Paleolithic [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-086 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Risovača Cave is a cave and archaeological site of the Paleolithic at Aranđelovac in central Serbia [SUPPORTED: https://en.wikipedia.org/wiki/Risova%C4%8Da_Cave]; The site was discovered around 1938 [SUPPORTED: https://en.wikipedia.org/wiki/Risova%C4%8Da_Cave]; The discovery came as a quarry began work [SUPPORTED: https://en.wikipedia.org/wiki/Risova%C4%8Da_Cave]; The cave held worked flint tools in its sediments [SUPPORTED: https://en.wikipedia.org/wiki/Risova%C4%8Da_Cave]; The cave held bone artifacts in its sediments [SUPPORTED: https://en.wikipedia.org/wiki/Risova%C4%8Da_Cave]; The artifacts are attributed to Neanderthals [SUPPORTED: https://en.wikipedia.org/wiki/Risova%C4%8Da_Cave]; The Neanderthal occupation dates to the end of the Middle Paleolithic [SUPPORTED: https://en.wikipedia.org/wiki/Risova%C4%8Da_Cave]"}]'::jsonb),
    ('f6b5aa36-d662-4490-a83b-1e5d857afdd5'::uuid, 'card_description', 'Where the Via Appia last touched the sea lay Sinuessa, near thermal springs Pliny says were esteemed a remedy for barrenness in women and insanity in men. The emperor Claudius came too.', 'Sinuessa was a city of Latium, in the more extended sense of the name, situated on the Tyrrhenian Sea, about 10 km north of the mouth of the Volturno River.', 'teaser-card-s016-rollback:f6b5aa36-d662-4490-a83b-1e5d857afdd5:card_description', 'rollback of teaser-card-s016: card_description ''Sinuessa was a city of Latium, in the more extended sense of the name, situated on the Tyrrhenian Sea, about 10 km north of the mouth of the Volturno River.'' restored on Sinuessa', '5f1c985bd9a48ebdcf8fab6355471536cfcad1071037e906a5d284f964172acc|43617901664c9eb7ea59d2e371549d69acd45625b2050af9f42e669eda7b95df|43617901664c9eb7ea59d2e371549d69acd45625b2050af9f42e669eda7b95df', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-029", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Where the Via Appia last touched the sea lay Sinuessa, near thermal springs Pliny says were esteemed a remedy for barrenness in women and insanity in men. The emperor Claudius came too."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-029 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Sinuessa lay where the Via Appia last touched the sea [S2]; Sinuessa was near thermal springs [S4]; Pliny says the springs were esteemed a remedy for barrenness in women [S5]; Pliny says the springs were esteemed a remedy for insanity in men [S5]; the emperor Claudius resorted to the springs [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-087 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Sinuessa was an ancient city (a Roman settlement/town) on the Tyrrhenian coast in Latium, in modern Sessa Aurunca, Campania, Italy [SUPPORTED: https://en.wikipedia.org/wiki/Sinuessa]; The Via Appia last touched the sea at Sinuessa [SUPPORTED: https://en.wikipedia.org/wiki/Sinuessa]; Sinuessa lay near thermal springs (the Aquae Sinuessanae) [SUPPORTED: https://en.wikipedia.org/wiki/Sinuessa]; Pliny says the springs were esteemed a remedy for barrenness in women and insanity in men [SUPPORTED: https://en.wikipedia.org/wiki/Sinuessa]; The emperor Claudius also came to the springs [SUPPORTED: https://en.wikipedia.org/wiki/Sinuessa]"}]'::jsonb),
    ('f7ed0deb-1206-4b70-b798-80ad7d442261'::uuid, 'card_description', 'Celts lived at Maastricht around 500 BC, where the Meuse ran shallow and easy to cross. It is not known when the Romans came, but in the 1st century AD they bridged the river here.', 'A Roman river crossing called Trajectum ad Mosam that grew into a medieval religious center. Neanderthal remains found here push the area''s human occupation back tens of thousands of years.', 'teaser-card-s016-rollback:f7ed0deb-1206-4b70-b798-80ad7d442261:card_description', 'rollback of teaser-card-s016: card_description "A Roman river crossing called Trajectum ad Mosam that grew into a medieval religious center. Neanderthal remains found here push the area''s human occupation back tens of thousands of years." restored on Maastricht', '3344c17d97dc956a27c3f71eed0531e647a2e80c7f10d09b2bc6ca970b4f4ac2|57c7861f920a8004d8d3cd5999099dfecf02531a12e6e358fac3a943529d0fea|57c7861f920a8004d8d3cd5999099dfecf02531a12e6e358fac3a943529d0fea', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-029", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Celts lived at Maastricht around 500 BC, where the Meuse ran shallow and easy to cross. It is not known when the Romans came, but in the 1st century AD they bridged the river here."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-029 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Celts lived at Maastricht around 500 BC [S3]; the Meuse was shallow and easy to cross there [S3]; it is not known when the Romans came to Maastricht [S4]; in the 1st century AD the Romans bridged the Meuse at Maastricht [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-087 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Maastricht is a settlement, a city in the southeastern Netherlands [SUPPORTED: https://en.wikipedia.org/wiki/Maastricht]; Celts lived at Maastricht around 500 BC [SUPPORTED: https://en.wikipedia.org/wiki/Maastricht]; The Meuse was shallow and easy to cross at that spot [SUPPORTED: https://en.wikipedia.org/wiki/Maastricht]; It is not known when the Romans came to Maastricht [SUPPORTED: https://en.wikipedia.org/wiki/Maastricht]; In the 1st century AD the Romans bridged the Meuse at Maastricht [SUPPORTED: https://en.wikipedia.org/wiki/Maastricht]"}]'::jsonb),
    ('f80f56c0-949f-4009-8658-f47cc3ca13fa'::uuid, 'card_description', 'Near Mingora in Swat, the Butkara Stupa was dressed in Hellenistic decorations in the 2nd century BCE. At the base of an Indo-Corinthian capital lay buried a reliquary and a coin of Azes II.', 'The Butkara Stupa is an important Buddhist stupa near Mingora, in the area of Swat.', 'teaser-card-s016-rollback:f80f56c0-949f-4009-8658-f47cc3ca13fa:card_description', 'rollback of teaser-card-s016: card_description ''The Butkara Stupa is an important Buddhist stupa near Mingora, in the area of Swat.'' restored on Butkara Stupa', '0a98424a8b4b180d4bd9978f5ae1985e2e227862e9bdf551a459414c9a457c47|71de9adbf3822a62550605fbd4d25ed6029a5510b50fa73d8fbb4dd2876e9b19|71de9adbf3822a62550605fbd4d25ed6029a5510b50fa73d8fbb4dd2876e9b19', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-029", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Near Mingora in Swat, the Butkara Stupa was dressed in Hellenistic decorations in the 2nd century BCE. At the base of an Indo-Corinthian capital lay buried a reliquary and a coin of Azes II."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-029 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the Butkara Stupa is near Mingora in Swat [S1]; the stupa received Hellenistic architectural decorations [S3]; the Hellenistic decorations were added in the 2nd century BCE [S3]; an Indo-Corinthian capital was found [S4]; a reliquary and a coin of Azes II were buried at the base of the capital [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-087 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Butkara Stupa is a Buddhist stupa near Mingora in Swat, Pakistan [SUPPORTED: https://en.wikipedia.org/wiki/Butkara_Stupa]; The stupa was given Hellenistic architectural decorations in the 2nd century BCE [SUPPORTED: https://en.wikipedia.org/wiki/Butkara_Stupa]; An Indo-Corinthian capital was found at the Butkara Stupa [SUPPORTED: https://en.wikipedia.org/wiki/Butkara_Stupa]; A reliquary was buried at the base of the Indo-Corinthian capital [SUPPORTED: https://en.wikipedia.org/wiki/Butkara_Stupa]; A coin of Azes II was buried at the base of the Indo-Corinthian capital [SUPPORTED: https://en.wikipedia.org/wiki/Butkara_Stupa]"}]'::jsonb),
    ('f8ccb519-328b-4b91-8c67-3416ee2aa788'::uuid, 'card_description', 'On Gozo, Santa Verna takes its name from a chapel of Saint Venera that once stood close to the temple. Excavations in 2015 revealed the temple''s five-apsed plan of the Ġgantija phase.', 'A Neolithic temple site in Xaghra, Gozo, occupied from around 5000 BC. Though heavily damaged, it was among the archipelago''s major megalithic temples — named for a later chapel to Saint Venera.', 'teaser-card-s016-rollback:f8ccb519-328b-4b91-8c67-3416ee2aa788:card_description', 'rollback of teaser-card-s016: card_description "A Neolithic temple site in Xaghra, Gozo, occupied from around 5000 BC. Though heavily damaged, it was among the archipelago''s major megalithic temples — named for a later chapel to Saint Venera." restored on Santa Verna', 'eb60f872b2c830efaac14c383df05ed53cb7c6b341a0e98b9f99b9f3f50fd1a2|df2a9a4b0dc514c3afac8331d465d559ff4f0c26e4f8c78257a5bfdebd412709|df2a9a4b0dc514c3afac8331d465d559ff4f0c26e4f8c78257a5bfdebd412709', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-rewrite-v-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "On Gozo, Santa Verna takes its name from a chapel of Saint Venera that once stood close to the temple. Excavations in 2015 revealed the temple''s five-apsed plan of the Ġgantija phase."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-v-003 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Santa Verna is on Gozo [S1]; Santa Verna takes its name from a chapel of Saint Venera [S3]; the chapel once stood close to the temple [S3]; excavations in 2015 revealed the temple''s five-apsed plan [W1]; the five-apsed plan belongs to the Ġgantija phase [W1]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify2-008 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Santa Verna is a megalithic temple site on the island of Gozo (Malta) [SUPPORTED: https://en.wikipedia.org/wiki/Santa_Verna]; Santa Verna was a (megalithic) temple [SUPPORTED: https://en.wikipedia.org/wiki/Santa_Verna]; The site takes its name from a chapel of Saint Venera [SUPPORTED: https://en.wikipedia.org/wiki/Santa_Verna]; The chapel of Saint Venera once stood close to the temple (no longer stands) [SUPPORTED: https://en.wikipedia.org/wiki/Santa_Verna]; Excavations took place in 2015 [SUPPORTED: https://en.wikipedia.org/wiki/Santa_Verna]; The 2015 excavations revealed the temple''s five-apsed plan [SUPPORTED: https://en.wikipedia.org/wiki/Santa_Verna]; The five-apsed plan belongs to the Ġgantija phase [SUPPORTED: https://en.wikipedia.org/wiki/Santa_Verna]"}, {"source": "web fact W1", "url": "https://en.wikipedia.org/wiki/Santa_Verna", "quote": "More extensive excavations funded by the European Research Council in 2015 revealed the five-apsed plan of the temple during the Ġgantija phase"}]'::jsonb),
    ('f947a367-a17a-4cb3-9d43-93965c88d3bf'::uuid, 'card_description', 'On the coastal plain of Veracruz, the stones of Zempoala came from the nearby river, covered in lime burned from shells and snails. At its peak it held between 25,000 and 30,000 people.', 'The Totonac capital of Totonacapan, occupied from around 1000 AD. Hernán Cortés arrived here in 1519 — the first major city the Spanish encountered — a meeting that shaped the entire conquest.', 'teaser-card-s016-rollback:f947a367-a17a-4cb3-9d43-93965c88d3bf:card_description', 'rollback of teaser-card-s016: card_description ''The Totonac capital of Totonacapan, occupied from around 1000 AD. Hernán Cortés arrived here in 1519 — the first major city the Spanish encountered — a meeting that shaped the entire conquest.'' restored on Zempoala', 'f84d5259a55c549c8f1adc964f9384e42e1a3dba23f9980c26769fb351033927|357030eab55a8a22f0bd86c4192180768d9796d6537409ad8d1062a5ffcff60b|357030eab55a8a22f0bd86c4192180768d9796d6537409ad8d1062a5ffcff60b', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-029", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "On the coastal plain of Veracruz, the stones of Zempoala came from the nearby river, covered in lime burned from shells and snails. At its peak it held between 25,000 and 30,000 people."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-029 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Zempoala lies on the coastal plain [S2]; Zempoala is in Veracruz [S1]; the stones of the structures came from the nearby river [S7]; the structures were covered in lime [S7]; the lime was burned from shells and snails [S7]; at its peak the population was between 25,000 and 30,000 [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-087 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Zempoala (Cempoala) is an important Mesoamerican archaeological site (a Totonac settlement) in the Mexican state of Veracruz [SUPPORTED: https://en.wikipedia.org/wiki/Cempoala]; Zempoala lies on the coastal plain of Veracruz [SUPPORTED: https://en.wikipedia.org/wiki/Cempoala]; The stones of Zempoala''s structures came from the nearby river [SUPPORTED: https://en.wikipedia.org/wiki/Cempoala]; The structures were covered in lime [SUPPORTED: https://en.wikipedia.org/wiki/Cempoala]; The lime was made by burning shells [SUPPORTED: https://en.wikipedia.org/wiki/Cempoala]; The lime was made by burning snails [SUPPORTED: https://en.wikipedia.org/wiki/Cempoala]; At its peak Zempoala held between 25,000 and 30,000 people [SUPPORTED: https://en.wikipedia.org/wiki/Cempoala]"}]'::jsonb),
    ('f978251d-d093-415a-8be0-c0e0de5d9d8e'::uuid, 'card_description', 'Vinovia, a Roman fort on a hill 15 metres above the Wear, was probably built to guard Dere Street''s crossing. By the early 6th century its buildings were being demolished for materials.', 'A Roman fort and settlement at Bishop Auckland whose military bathhouse preserves a near-complete hypocaust heating system — the most intact example of its type from Roman Britain.', 'teaser-card-s016-rollback:f978251d-d093-415a-8be0-c0e0de5d9d8e:card_description', 'rollback of teaser-card-s016: card_description ''A Roman fort and settlement at Bishop Auckland whose military bathhouse preserves a near-complete hypocaust heating system — the most intact example of its type from Roman Britain.'' restored on Vinovia', '04e2720cae0517283d63bfc3cb398acdc0b2d763c9a7a08b3146e492c678711e|8c244de61f1f88a141282982806cca17760a80a063fb28795e5ed377308429d8|8c244de61f1f88a141282982806cca17760a80a063fb28795e5ed377308429d8', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-rewrite1-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Vinovia, a Roman fort on a hill 15 metres above the Wear, was probably built to guard Dere Street''s crossing. By the early 6th century its buildings were being demolished for materials."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check1-002 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Vinovia was a Roman fort [S1]; the fort sat on a hill [S3]; the hill is 15 metres above the Wear [S3]; the fort was probably built (established) to guard a crossing [S2]; the crossing is the one of the Wear by Dere Street [S2]; by the early 6th century the demolition of its buildings for their materials had begun [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-088 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Vinovia was a Roman fort (central claim: kind of place; on the Wear in County Durham, England) [SUPPORTED: https://en.wikipedia.org/wiki/Vinovia]; The fort stood on a hill [SUPPORTED: https://en.wikipedia.org/wiki/Vinovia]; The hill is 15 metres above the river [SUPPORTED: https://en.wikipedia.org/wiki/Vinovia]; The river is the Wear [SUPPORTED: https://en.wikipedia.org/wiki/Vinovia]; The fort was probably established/built to guard a crossing [SUPPORTED: https://en.wikipedia.org/wiki/Vinovia]; The crossing guarded is Dere Street''s crossing of the Wear [SUPPORTED: https://en.wikipedia.org/wiki/Vinovia]; By the early 6th century the demolition of the fort had started [SUPPORTED: https://en.wikipedia.org/wiki/Vinovia]; The fort''s buildings were demolished for reclamation of their materials [SUPPORTED: https://en.wikipedia.org/wiki/Vinovia]"}]'::jsonb),
    ('f9cfcc0f-960a-4184-b72d-ab054ed01221'::uuid, 'card_description', 'At Krasnyi Yar, a large Botai culture site in Kazakhstan, the only livestock bones found were horses: eaten, likely held in corrals, their bones made into tools for working leather.', '5th-3rd-millennium BC Botai culture site with early evidence of horse corrals: curved post-hole rows and nitrogen deposits in enclosed areas indicate horses were penned long before cavalry was known.', 'teaser-card-s016-rollback:f9cfcc0f-960a-4184-b72d-ab054ed01221:card_description', 'rollback of teaser-card-s016: card_description ''5th-3rd-millennium BC Botai culture site with early evidence of horse corrals: curved post-hole rows and nitrogen deposits in enclosed areas indicate horses were penned long before cavalry was known.'' restored on Krasnyi Yar, Kazakhstan', '7bcb6ee91e98950d4f20658c7b7ba4aa44a5da3b007c491e900196b801707c9f|962f318e7fb3af285766f32e730f6aeccdf302194d5713ae1c7cf2eef35650f1|962f318e7fb3af285766f32e730f6aeccdf302194d5713ae1c7cf2eef35650f1', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-030", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "At Krasnyi Yar, a large Botai culture site in Kazakhstan, the only livestock bones found were horses: eaten, likely held in corrals, their bones made into tools for working leather."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-030 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Krasnyi Yar is a large site [S2]; it is a site of the Botai culture [S1]; it is in Kazakhstan [S1]; the only livestock bones found at the site were horse bones [S4]; horses were eaten [S3]; horses were likely held in corrals (the researchers'' inference) [S4]; horse bones were made into tools [S5]; the bone tools were for working leather [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-088 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Krasnyi Yar is a Botai culture site (central claim: kind of place) [SUPPORTED: https://en.wikipedia.org/wiki/Krasnyi_Yar_(Kazakhstan)]; The site is in Kazakhstan [SUPPORTED: https://en.wikipedia.org/wiki/Krasnyi_Yar_(Kazakhstan)]; The site is large [SUPPORTED: https://en.wikipedia.org/wiki/Krasnyi_Yar_(Kazakhstan)]; The only livestock bones found at the site were horses [SUPPORTED: https://en.wikipedia.org/wiki/Krasnyi_Yar_(Kazakhstan)]; The horses were eaten [SUPPORTED: https://en.wikipedia.org/wiki/Krasnyi_Yar_(Kazakhstan)]; The horses were held in corrals (inferred) [SUPPORTED: https://en.wikipedia.org/wiki/Krasnyi_Yar_(Kazakhstan)]; The evidence for a corral is curved rows of postholes and nitrogen and phosphates in the enclosed areas [SUPPORTED: https://en.wikipedia.org/wiki/Krasnyi_Yar_(Kazakhstan)]; Horse bones were made into tools [SUPPORTED: https://en.wikipedia.org/wiki/Krasnyi_Yar_(Kazakhstan)]; The bone tools were used for working leather (leather production) [SUPPORTED: https://en.wikipedia.org/wiki/Krasnyi_Yar_(Kazakhstan)]"}]'::jsonb),
    ('f9f8e1fa-4460-419a-97cf-1e0e2fb6a565'::uuid, 'card_description', 'On the slopes of Mount Othrys, Xyniae once controlled the passages by the lake that took its name. Plundered in 198 BC, it later saw a castle rise amid the ruins of its ancient acropolis.', 'Xyniae or Xyniai or Xynia was an ancient city in Achaea Phthiotis, Ancient Thessaly.', 'teaser-card-s016-rollback:f9f8e1fa-4460-419a-97cf-1e0e2fb6a565:card_description', 'rollback of teaser-card-s016: card_description ''Xyniae or Xyniai or Xynia was an ancient city in Achaea Phthiotis, Ancient Thessaly.'' restored on Xyniae', 'f2f844cee17142d584b5dbafb06dfb865c0ebdab1d9dccf190ef9cd8d2f9a4dd|34b73181db217dad4384d1bcafe51f9d4d3cdc97adf63a3d984c15453bbbd961|34b73181db217dad4384d1bcafe51f9d4d3cdc97adf63a3d984c15453bbbd961', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-030", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "On the slopes of Mount Othrys, Xyniae once controlled the passages by the lake that took its name. Plundered in 198 BC, it later saw a castle rise amid the ruins of its ancient acropolis."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-030 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Xyniae lay on the slopes of Mount Othrys [S2]; the city once controlled the passages by the lake [S3]; the lake took its name from the city [S3]; the city was plundered in 198 BC [S4]; a castle was later built amid the ruins of the ancient acropolis [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-088 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Xyniae was an ancient city in Achaea Phthiotis, Thessaly, Greece (central claim: kind of place and location) [SUPPORTED: https://en.wikipedia.org/wiki/Xyniae]; The city lay on the slopes of Mount Othrys [SUPPORTED: https://en.wikipedia.org/wiki/Xyniae]; Xyniae controlled the passages by the lake that took its name (Lake Xynias) [SUPPORTED: https://en.wikipedia.org/wiki/Xyniae]; Xyniae was plundered in 198 BC [SUPPORTED: https://en.wikipedia.org/wiki/Xyniae]; A castle later rose amid the ruins of its ancient acropolis [SUPPORTED: https://en.wikipedia.org/wiki/Xyniae]"}]'::jsonb),
    ('fa2bcb15-3d7f-4c62-8215-514ae296e375'::uuid, 'card_description', 'Windmill Hill, the largest known causewayed enclosure in Britain, rings its hilltop with three segmented ditches, the outermost 365 metres across, crossed by causeways up to 7 m wide.', 'The largest known causewayed enclosure in Britain, built around 3700 BC near Avebury. Three concentric segmented ditches surrounded the hilltop as part of the Avebury ritual landscape.', 'teaser-card-s016-rollback:fa2bcb15-3d7f-4c62-8215-514ae296e375:card_description', 'rollback of teaser-card-s016: card_description ''The largest known causewayed enclosure in Britain, built around 3700 BC near Avebury. Three concentric segmented ditches surrounded the hilltop as part of the Avebury ritual landscape.'' restored on Windmill Hill, Avebury', 'f2fc491f7354465489a1f25d89603f5710d13eb47e1ef4b6f305750020fac4be|e89dd60974909a806de43ad047a8d32ee1aba6ca23c606fd83258dfc278ab641|e89dd60974909a806de43ad047a8d32ee1aba6ca23c606fd83258dfc278ab641', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-030", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Windmill Hill, the largest known causewayed enclosure in Britain, rings its hilltop with three segmented ditches, the outermost 365 metres across, crossed by causeways up to 7 m wide."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-030 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Windmill Hill is the largest known causewayed enclosure in Britain [S2]; it is a causewayed enclosure on a hilltop [S1, S4]; three segmented ditches ring the hilltop [S4]; the outermost ditch is 365 metres across [S4]; causeways cross the ditches [S5]; the causeways are up to 7 m wide [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-088 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Windmill Hill is a causewayed enclosure (central claim: kind of place; Wiltshire, England) [SUPPORTED: https://en.wikipedia.org/wiki/Windmill_Hill,_Avebury]; The enclosure is on a hilltop [SUPPORTED: https://en.wikipedia.org/wiki/Windmill_Hill,_Avebury]; It is the largest known causewayed enclosure in Britain [SUPPORTED: https://en.wikipedia.org/wiki/Windmill_Hill,_Avebury]; There are three ditches ringing the hilltop [SUPPORTED: https://en.wikipedia.org/wiki/Windmill_Hill,_Avebury]; The ditches are segmented [SUPPORTED: https://en.wikipedia.org/wiki/Windmill_Hill,_Avebury]; The outermost ditch is 365 metres across [SUPPORTED: https://en.wikipedia.org/wiki/Windmill_Hill,_Avebury]; The ditches are crossed (interrupted) by causeways [SUPPORTED: https://en.wikipedia.org/wiki/Windmill_Hill,_Avebury]; The causeways are up to 7 m wide [SUPPORTED: https://en.wikipedia.org/wiki/Windmill_Hill,_Avebury]"}]'::jsonb),
    ('fae3bb4b-85fb-427a-a896-f32f4a2aa69c'::uuid, 'card_description', 'Three round barrows, and possibly a long chambered one, make up Battlegore Burial Chamber in Somerset, where bronze finds include a rapier, a spearhead, a winged axe and a broken dagger.', 'Bronze Age burial mounds in Somerset, its medieval name ''Battlegore'' attached after a Danish raid in 918 AD. Three round barrows, possibly a long chambered barrow, referenced since the 14th century.', 'teaser-card-s016-rollback:fae3bb4b-85fb-427a-a896-f32f4a2aa69c:card_description', 'rollback of teaser-card-s016: card_description "Bronze Age burial mounds in Somerset, its medieval name ''Battlegore'' attached after a Danish raid in 918 AD. Three round barrows, possibly a long chambered barrow, referenced since the 14th century." restored on Battlegore Burial Chamber', '9ad2141e46ad434ca3e321dc640b12615982dab221b59b89a13ee6a9292394dd|ba71b0f6bbd77491adff4aa9f9e002e67df6876a0b08cff226d3f9411cde861e|ba71b0f6bbd77491adff4aa9f9e002e67df6876a0b08cff226d3f9411cde861e', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-030", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Three round barrows, and possibly a long chambered one, make up Battlegore Burial Chamber in Somerset, where bronze finds include a rapier, a spearhead, a winged axe and a broken dagger."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-030 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Battlegore Burial Chamber is made up of three round barrows [S2]; possibly also a long chambered barrow [S2]; the site is in Somerset [S1]; bronze finds include a rapier [S6]; bronze finds include a spearhead [S6]; bronze finds include a winged axe [S6]; bronze finds include a broken dagger [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-088 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Battlegore Burial Chamber is a burial chamber (central claim: kind of place) [SUPPORTED: https://en.wikipedia.org/wiki/Battlegore_Burial_Chamber]; The site is in Somerset [SUPPORTED: https://en.wikipedia.org/wiki/Battlegore_Burial_Chamber]; The site includes three round barrows [SUPPORTED: https://en.wikipedia.org/wiki/Battlegore_Burial_Chamber]; The site possibly includes a long chambered barrow [SUPPORTED: https://en.wikipedia.org/wiki/Battlegore_Burial_Chamber]; The finds include bronze items [SUPPORTED: https://en.wikipedia.org/wiki/Battlegore_Burial_Chamber]; Bronze finds include a rapier [SUPPORTED: https://en.wikipedia.org/wiki/Battlegore_Burial_Chamber]; Bronze finds include a spearhead [SUPPORTED: https://en.wikipedia.org/wiki/Battlegore_Burial_Chamber]; Bronze finds include a winged axe [SUPPORTED: https://en.wikipedia.org/wiki/Battlegore_Burial_Chamber]; Bronze finds include a broken dagger [SUPPORTED: https://en.wikipedia.org/wiki/Battlegore_Burial_Chamber]"}]'::jsonb),
    ('fc337c87-1194-4407-b440-2b91f93dbdc7'::uuid, 'card_description', NULL, 'Zafarraya is known for a Neanderthal mandible found in a cave in 1983 by Cecilio Barroso and Paqui Medina.', 'teaser-card-s016-rollback:fc337c87-1194-4407-b440-2b91f93dbdc7:card_description', 'rollback of teaser-card-s016: card_description ''Zafarraya is known for a Neanderthal mandible found in a cave in 1983 by Cecilio Barroso and Paqui Medina.'' restored on Zafarraya', '||b34124238458339ff6bbf6fb8aedd96c10cac0da2cd64be19def94760fb47dba', '[{"source": "lane WB run wb-ws-2026-09-27-01: failed-after-verify-rewrite", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The web check contradicts: The Neanderthal jaw is dated to 30,000 years BP (https://pmc.ncbi.nlm.nih.gov/articles/PMC3581959/: \"Although these results can only be used to tentatively suggest that these remains date close to or beyond the limit of radiocarbon, they cast into doubt the previous post-42 ka calBP chronology.\"); The web check contradicts: The find is early proof that Neanderthals and modern humans overlapped in Europe (https://pmc.ncbi.nlm.nih.gov/articles/PMC3581959/: \"This collection of Neanderthals should no longer be cited as providing evidence for the southern Iberian Neanderthal late refugia.\"); No sentence of the description supports the claim: Zafarraya is in Spain; No sentence says Zafarraya is in Spain: S1-S4 name no country or region, and the country appears only in the site header, so the opening ''In Spain'' has no support and must be removed or replaced by a place the sentences state."}]'::jsonb),
    ('fc9b4ac3-3e4a-42d0-96f1-81f37f246230'::uuid, 'card_description', 'The Forum Baths of Roman Trier stayed in use through the end of the fourth century. Then Trier was sacked again and again; from the 13th century the ruins were quarried for local buildings.', 'Roman baths converted from 2nd-century buildings, with the hot rooms facing south and cold rooms facing north to use the sun''s heat. One of several bathhouses in the imperial capital.', 'teaser-card-s016-rollback:fc9b4ac3-3e4a-42d0-96f1-81f37f246230:card_description', 'rollback of teaser-card-s016: card_description "Roman baths converted from 2nd-century buildings, with the hot rooms facing south and cold rooms facing north to use the sun''s heat. One of several bathhouses in the imperial capital." restored on Forum Baths, Trier', '863d8621f3127a1aaae98ba48b7d79fa8b3612149a5ec9d512672b100bd3581c|d333a0c872dec0571f42a8554b947505da09c3d7ddf303753a4704095ed0554f|d333a0c872dec0571f42a8554b947505da09c3d7ddf303753a4704095ed0554f', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-030", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Forum Baths of Roman Trier stayed in use through the end of the fourth century. Then Trier was sacked again and again; from the 13th century the ruins were quarried for local buildings."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-030 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the Forum Baths belong to Roman Trier [S1]; the baths stayed in use through the end of the fourth century [S2]; Trier was sacked repeatedly, after which the complex fell out of use [S3]; from the 13th century the ruins were quarried [S4]; the quarried stone was used for local buildings [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-089 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Forum Baths are a Roman bath complex, now a ruin [SUPPORTED: https://en.wikipedia.org/wiki/Forum_Baths,_Trier]; The baths are in Roman Trier (Augusta Treverorum, modern Trier), Germany [SUPPORTED: https://en.wikipedia.org/wiki/Forum_Baths,_Trier]; The Forum Baths stayed in use through the end of the fourth century [SUPPORTED: https://en.wikipedia.org/wiki/Forum_Baths,_Trier]; After that Trier was sacked again and again [SUPPORTED: https://en.wikipedia.org/wiki/Forum_Baths,_Trier]; From the 13th century the ruins were quarried [SUPPORTED: https://en.wikipedia.org/wiki/Forum_Baths,_Trier]; The quarried stone went into local buildings [SUPPORTED: https://en.wikipedia.org/wiki/Forum_Baths,_Trier]"}]'::jsonb),
    ('fcc4232a-0c79-42c7-ae83-cb6bd8fa98bd'::uuid, 'card_description', 'On the eastern outskirts of Mġarr, the two adjacent Ta'' Ħaġrat Temples stand on the site of a village that predates them. Sir Temi Zammit excavated the site between 1923 and 1926.', 'UNESCO-listed temples from 3600–3000 BC, among the oldest religious structures on Earth. The facade closely resembles the nearby Ggantija temples.', 'teaser-card-s016-rollback:fcc4232a-0c79-42c7-ae83-cb6bd8fa98bd:card_description', 'rollback of teaser-card-s016: card_description ''UNESCO-listed temples from 3600–3000 BC, among the oldest religious structures on Earth. The facade closely resembles the nearby Ggantija temples.'' restored on Ta'' Ħaġrat Temples', '8be8b242957d4795c27bd0a21251a451eefbd476b461a41467f666517be3c721|bf21101f68ad03379b9dd3efc658e4b84115b075d49e5b1d4d5f9033c09c82fc|bf21101f68ad03379b9dd3efc658e4b84115b075d49e5b1d4d5f9033c09c82fc', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-rewrite-v-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "On the eastern outskirts of Mġarr, the two adjacent Ta'' Ħaġrat Temples stand on the site of a village that predates them. Sir Temi Zammit excavated the site between 1923 and 1926."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-v-003 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the Ta'' Ħaġrat Temples are on the eastern outskirts of Mġarr [S3]; there are two adjacent temples [S7]; a village stood on the site of the temples [S4]; the village predates the temples [S4]; Sir Temi Zammit excavated the site [S8]; the excavation took place between 1923 and 1926 [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify2-008 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Ta'' Ħaġrat Temples are megalithic temples in Mġarr, Malta (central claim: the site is a pair of prehistoric temples, in Malta) [SUPPORTED: https://en.wikipedia.org/wiki/Ta%27_%C4%A6a%C4%A1rat]; The temples lie on the eastern outskirts of Mġarr [SUPPORTED: https://en.wikipedia.org/wiki/Ta%27_%C4%A6a%C4%A1rat]; There are two temples [SUPPORTED: https://en.wikipedia.org/wiki/Ta%27_%C4%A6a%C4%A1rat]; The two temples are adjacent to each other [SUPPORTED: https://en.wikipedia.org/wiki/Ta%27_%C4%A6a%C4%A1rat]; A village stood on the site where the temples stand [SUPPORTED: https://en.wikipedia.org/wiki/Ta%27_%C4%A6a%C4%A1rat]; The village predates the temples [SUPPORTED: https://en.wikipedia.org/wiki/Ta%27_%C4%A6a%C4%A1rat]; Sir Temi Zammit excavated the site [SUPPORTED: https://en.wikipedia.org/wiki/Ta%27_%C4%A6a%C4%A1rat]; The excavation by Zammit took place between 1923 and 1926 [SUPPORTED: https://en.wikipedia.org/wiki/Ta%27_%C4%A6a%C4%A1rat]"}]'::jsonb),
    ('fce614a8-8697-45d3-9574-4b092231b0bd'::uuid, 'card_description', 'In the upper Asón River valley, El Mirón Cave holds Upper Paleolithic art and the skeleton of the Red Lady, a woman estimated to have died around 18,700 years ago, discovered only in 2010.', NULL, 'teaser-card-s016-rollback:fce614a8-8697-45d3-9574-4b092231b0bd:card_description', 'rollback of teaser-card-s016: card_description None restored on El Mirón Cave', '7b70e2688514e4c1ab63832cd3d6422321ef2870b388101f6515fce04990ab41|9b5956fb5c9c58738500a97129d7e444b1b81208b3a3f332ee744b8175f0f0c3|9b5956fb5c9c58738500a97129d7e444b1b81208b3a3f332ee744b8175f0f0c3', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-030", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "In the upper Asón River valley, El Mirón Cave holds Upper Paleolithic art and the skeleton of the Red Lady, a woman estimated to have died around 18,700 years ago, discovered only in 2010."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-030 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "El Mirón Cave lies in the upper Asón River valley [S1]; the cave holds Upper Paleolithic art [S6]; the cave holds the skeleton of the Red Lady [S3]; the Red Lady was a woman [S3]; she is estimated to have died around 18,700 years ago [S4]; she was discovered in 2010 [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-089 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "El Mirón Cave is a cave and archaeological site in Cantabria, Spain [SUPPORTED: https://es.wikipedia.org/wiki/Cueva_de_El_Mir%C3%B3n]; The cave lies in the upper Asón River valley [SUPPORTED: https://en.wikipedia.org/wiki/El_Mir%C3%B3n_Cave]; The cave holds Upper Paleolithic art [SUPPORTED: https://en.wikipedia.org/wiki/El_Mir%C3%B3n_Cave]; The cave holds the skeleton of the Red Lady, a woman [SUPPORTED: https://en.wikipedia.org/wiki/El_Mir%C3%B3n_Cave]; The Red Lady is estimated to have died around 18,700 years ago [SUPPORTED: https://archaeology.org/issues/september-october-2015/digs-discoveries/trenches-spain-paleolithic-red-lady-el-miron/]; The Red Lady was discovered only in 2010 [SUPPORTED: https://en.wikipedia.org/wiki/El_Mir%C3%B3n_Cave]"}]'::jsonb),
    ('fd2f475b-845a-42ec-8183-264673911980'::uuid, 'card_description', 'Just north of Bad Buchau, the lake Federsee is surrounded by moorland, partially overgrown with reeds. Its basin is famous for excavations of Stone Age and Bronze Age artifacts.', 'A lake surrounded by moorland where Stone Age and Bronze Age pile dwellings were preserved in waterlogged sediment. The anaerobic conditions kept organic artifacts intact.', 'teaser-card-s016-rollback:fd2f475b-845a-42ec-8183-264673911980:card_description', 'rollback of teaser-card-s016: card_description ''A lake surrounded by moorland where Stone Age and Bronze Age pile dwellings were preserved in waterlogged sediment. The anaerobic conditions kept organic artifacts intact.'' restored on Federsee', '0d537c5910ef3339edae24653ad4ada2c32f2619ca34eb453c286c65669599dc|240427c044b666f81704aa2e7b18b41acd8762fc779ad386bdb18ff1024feebc|240427c044b666f81704aa2e7b18b41acd8762fc779ad386bdb18ff1024feebc', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-rewrite-v-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Just north of Bad Buchau, the lake Federsee is surrounded by moorland, partially overgrown with reeds. Its basin is famous for excavations of Stone Age and Bronze Age artifacts."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-v-003 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Federsee is a lake [S1]; Federsee lies just north of Bad Buchau [S1]; the lake is surrounded by moorland [S2]; the moorland is partially overgrown with reeds [S2]; the basin of the lake is famous for excavations of Stone Age artifacts [S5]; the basin of the lake is famous for excavations of Bronze Age artifacts [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify2-008 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Federsee is a lake in Southern Germany (central claim: the site is a lake basin with prehistoric finds, in Germany) [SUPPORTED: https://en.wikipedia.org/wiki/Federsee]; The lake lies just north of Bad Buchau [SUPPORTED: https://en.wikipedia.org/wiki/Federsee]; The lake is surrounded by moorland [SUPPORTED: https://en.wikipedia.org/wiki/Federsee]; The moorland is partially overgrown with reeds [SUPPORTED: https://en.wikipedia.org/wiki/Federsee]; The Federsee basin is famous for its excavations [SUPPORTED: https://en.wikipedia.org/wiki/Federsee]; The excavations yielded Stone Age artifacts [SUPPORTED: https://en.wikipedia.org/wiki/Federsee]; The excavations yielded Bronze Age artifacts [SUPPORTED: https://en.wikipedia.org/wiki/Federsee]"}]'::jsonb),
    ('fe021c51-e3fb-407d-9f6c-b770ba056f15'::uuid, 'card_description', 'Bacho Kiro Cave is a four-storey labyrinth of galleries and corridors, 3,600 m long in total. It yielded the oldest human remains ever found in Bulgaria, shown to be those of Homo sapiens.', NULL, 'teaser-card-s016-rollback:fe021c51-e3fb-407d-9f6c-b770ba056f15:card_description', 'rollback of teaser-card-s016: card_description None restored on Bacho Kiro Cave', '4bd72b336b31f777c31664c8ab520f366aa304ffada82135028fef7417c3363e|ff060b3487a36e16cc5e354ac688f0f289618f04d7b07a4e72bd4331dc994410|ff060b3487a36e16cc5e354ac688f0f289618f04d7b07a4e72bd4331dc994410', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-rewrite-v-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Bacho Kiro Cave is a four-storey labyrinth of galleries and corridors, 3,600 m long in total. It yielded the oldest human remains ever found in Bulgaria, shown to be those of Homo sapiens."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-v-003 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Bacho Kiro Cave is a four-storey labyrinth of galleries and corridors [S3]; its total length is 3,600 m [S3]; the site yielded the oldest human remains ever found in Bulgaria [S4]; those human remains were shown to be those of Homo sapiens [S4, S7, S8]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify2-008 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Bacho Kiro Cave is a cave in Bulgaria (central claim: the site is a cave, near Dryanovo, Bulgaria) [SUPPORTED: https://en.wikipedia.org/wiki/Bacho_Kiro_cave]; The cave is a four-storey labyrinth of galleries and corridors [SUPPORTED: https://en.wikipedia.org/wiki/Bacho_Kiro_cave]; The cave is 3,600 m long in total [SUPPORTED: https://en.wikipedia.org/wiki/Bacho_Kiro_cave]; The site yielded the oldest human remains ever found in Bulgaria [SUPPORTED: https://en.wikipedia.org/wiki/Bacho_Kiro_cave]; Those remains were shown to be Homo sapiens (not Neanderthals) [SUPPORTED: https://en.wikipedia.org/wiki/Bacho_Kiro_cave]"}]'::jsonb),
    ('fee01523-1686-437c-97ef-9e3566fba1c3'::uuid, 'card_description', 'On a steep scarp near the summit of Craig y Llyn, Foel Chwern, a Bronze Age burial cairn of small stones, looks far to the north. A partial dig found neither burials nor any other finds.', 'Foel Chwern is a Round cairn on the edge of the high plateau east of the Neath valley, and near the summit of Craig y Llyn.', 'teaser-card-s016-rollback:fee01523-1686-437c-97ef-9e3566fba1c3:card_description', 'rollback of teaser-card-s016: card_description ''Foel Chwern is a Round cairn on the edge of the high plateau east of the Neath valley, and near the summit of Craig y Llyn.'' restored on Foel Chwern', '8df4e742b077f647d3ce98fe75dd7f74d9b4607b6ee1d556eb9314f531541f68|7bdcbc47596521d19a366c107a7cafd91b73ffb7479e35cfbcad8688ed327d19|7bdcbc47596521d19a366c107a7cafd91b73ffb7479e35cfbcad8688ed327d19', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-030", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "On a steep scarp near the summit of Craig y Llyn, Foel Chwern, a Bronze Age burial cairn of small stones, looks far to the north. A partial dig found neither burials nor any other finds."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-030 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Foel Chwern lies on a steep scarp [S3]; it is near the summit of Craig y Llyn [S1]; it is a Bronze Age burial cairn [S3]; the cairn is made of small stones [S4]; it has a wide view far to the north [S3]; a partial excavation found no burials [S6]; the partial excavation found no other finds [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-090 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Foel Chwern is a burial cairn (the central claim: what kind of place it is). [SUPPORTED: https://cadwpublic-api.azurewebsites.net/reports/sam/FullReport?id=2883]; The burial cairn dates to the Bronze Age. [SUPPORTED: https://cadwpublic-api.azurewebsites.net/reports/sam/FullReport?id=2883]; Foel Chwern lies near the summit of Craig y Llyn. [SUPPORTED: https://en.wikipedia.org/wiki/Foel_Chwern]; Craig y Llyn, and so Foel Chwern, is in Wales (South Wales). [SUPPORTED: https://en.wikipedia.org/wiki/Craig_y_Llyn]; The cairn sits on a steep scarp and looks far to the north (wide field of view to the north). [SUPPORTED: https://en.wikipedia.org/wiki/Foel_Chwern]; The cairn is made of small stones. [SUPPORTED: https://en.wikipedia.org/wiki/Foel_Chwern]; The cairn was only partly excavated. [SUPPORTED: https://cadwpublic-api.azurewebsites.net/reports/sam/FullReport?id=2883]; The partial excavation found neither burials nor any other finds (implies the burial function is inferred, not proven by remains). [SUPPORTED: https://cadwpublic-api.azurewebsites.net/reports/sam/FullReport?id=2883]"}]'::jsonb),
    ('ff136c0c-2d3a-4621-b27b-294758b9cc4d'::uuid, 'card_description', 'Probably the last treasury built in the sanctuary of Apollo at Delphi, the Treasury of Cyrene faced his temple, a Doric building raised in marble from Paros and Mount Pentelikon.', '4th-century BC treasury at Delphi, built ~334-322 BC by Cyrene in gratitude for the wheat it donated during a lean period. The last treasury raised in the sanctuary of Apollo, facing the god''s temple.', 'teaser-card-s016-rollback:ff136c0c-2d3a-4621-b27b-294758b9cc4d:card_description', 'rollback of teaser-card-s016: card_description "4th-century BC treasury at Delphi, built ~334-322 BC by Cyrene in gratitude for the wheat it donated during a lean period. The last treasury raised in the sanctuary of Apollo, facing the god''s temple." restored on Treasury of Cyrene', '5f682c6ca782d938365e9ed05ca30c1c75599872263dca8be3b3c6f267fbe505|6fe0592d31e96bae5bdbe3f2fa15a8e5d57e1e33d4f508ba1fb8f3899198d7fc|6fe0592d31e96bae5bdbe3f2fa15a8e5d57e1e33d4f508ba1fb8f3899198d7fc', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-030", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Probably the last treasury built in the sanctuary of Apollo at Delphi, the Treasury of Cyrene faced his temple, a Doric building raised in marble from Paros and Mount Pentelikon."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-030 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the Treasury of Cyrene was probably the last treasury built in the sanctuary of Apollo [S2]; the sanctuary is at Delphi [S1]; the treasury faced the Temple of Apollo [S3]; it was a Doric building [S7]; its elevation was made of marble [S6]; the marble came from Paros and Mount Pentelikon [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-090 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Treasury of Cyrene was a treasury building in the sanctuary of Apollo at Delphi (the central claim: what and where it is). [SUPPORTED: https://en.wikipedia.org/wiki/Treasury_of_Cyrene]; Delphi, with its sanctuary, is in Greece. [SUPPORTED: https://en.wikipedia.org/wiki/Delphi]; It was probably the last treasury built in the sanctuary of Apollo. [SUPPORTED: http://e-delphi.gr/en-gb/site/monuments/thetreasuryofthecyreneans.aspx]; The treasury faced the temple of Apollo (\"his temple\"). [SUPPORTED: http://e-delphi.gr/en-gb/site/monuments/thetreasuryofthecyreneans.aspx]; It was a Doric building. [SUPPORTED: http://e-delphi.gr/en-gb/site/monuments/thetreasuryofthecyreneans.aspx]; It was raised in marble from Paros and from Mount Pentelikon. [SUPPORTED: http://e-delphi.gr/en-gb/site/monuments/thetreasuryofthecyreneans.aspx]; The marble came from both Paros and Pentelikon (second source). [SUPPORTED: https://delphi.culture.gr/the-treasure-of-the-kirenae/]"}]'::jsonb),
    ('ff55d038-92b0-4fad-9973-96cab63ec8db'::uuid, 'card_description', 'A sphinx brought from Egypt stands before the Temple of Jupiter in Diocletian''s Palace. When the emperor unexpectedly abdicated in 305, work stopped, leaving parts of the temple unfinished.', 'The Temple of Jupiter was constructed between 295 and 305 as part of Diocletian''s Palace.', 'teaser-card-s016-rollback:ff55d038-92b0-4fad-9973-96cab63ec8db:card_description', 'rollback of teaser-card-s016: card_description "The Temple of Jupiter was constructed between 295 and 305 as part of Diocletian''s Palace." restored on Temple of Jupiter, Split', '37f20446fc76d1d91c0897e77b27179d5f6bf8b768ad56a9f604d83fe32ac1eb|e4219abb009cdda6f336f99e9bda06123050d37737af7d692703dcc7826d9898|e4219abb009cdda6f336f99e9bda06123050d37737af7d692703dcc7826d9898', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-030", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "A sphinx brought from Egypt stands before the Temple of Jupiter in Diocletian''s Palace. When the emperor unexpectedly abdicated in 305, work stopped, leaving parts of the temple unfinished."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-030 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "a sphinx brought from Egypt stands before the Temple of Jupiter [S3]; the temple is in Diocletian''s Palace [S2, S4]; the emperor unexpectedly abdicated in 305 [S5]; work stopped when he abdicated [S5]; parts of the temple were left unfinished [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-090 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Temple of Jupiter is a temple in Split, Croatia, inside Diocletian''s Palace (the central claim: what and where it is). [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Jupiter,_Split]; The temple stands in the western part of Diocletian''s Palace. [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Jupiter,_Split]; A sphinx brought from Egypt stands before the temple. [SUPPORTED: https://visitsplit.com/en/526/temple-of-jupiter]; The emperor (Diocletian) abdicated in 305. [SUPPORTED: https://en.wikipedia.org/wiki/Diocletian%27s_Palace]; The abdication was unexpected. [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Jupiter,_Split]; Work stopped upon the abdication, leaving parts of the temple unfinished. [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Jupiter,_Split]"}]'::jsonb),
    ('ff7fc6c8-04f1-4988-954c-99c9b9f113e4'::uuid, 'card_description', 'At the mouth of the Chorokhi river on the Black Sea, the Roman walls of Gonio Fortress still keep 18 of their 22 towers. Its oldest mention comes from Pliny the Elder, in the 1st century AD.', 'The fortress is rectangular, and was built with four gates and 22 towers along the circuit of walls enclosing the site; 18 of the towers still survive.', 'teaser-card-s016-rollback:ff7fc6c8-04f1-4988-954c-99c9b9f113e4:card_description', 'rollback of teaser-card-s016: card_description ''The fortress is rectangular, and was built with four gates and 22 towers along the circuit of walls enclosing the site; 18 of the towers still survive.'' restored on Gonio Fortress', '3bbdd6ec8cfc1976b82274687ce47e27e8f2f822554137679719ef76104db143|2b03a1d9fc49d7eb5cf05c19d0e3c052279f672be847d2cfcd7bc27c3c7d45a3|2b03a1d9fc49d7eb5cf05c19d0e3c052279f672be847d2cfcd7bc27c3c7d45a3', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-030", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "At the mouth of the Chorokhi river on the Black Sea, the Roman walls of Gonio Fortress still keep 18 of their 22 towers. Its oldest mention comes from Pliny the Elder, in the 1st century AD."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-030 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the fortress is at the mouth of the Chorokhi river [S1]; it is on the Black Sea [S1]; Gonio Fortress has Roman walls [S1, S8]; the fortress was built with 22 towers [S8]; 18 of the 22 towers still survive [S8]; its oldest mention comes from Pliny the Elder [S2]; the mention dates to the 1st century AD [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-090 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Gonio Fortress is a Roman fortress in Georgia (the central claim: what kind of place it is, with the Roman walls). [SUPPORTED: https://visitbatumi.com/en/fortresses-092/Gonio-Apsaros-fortress]; The fortress lies at the mouth of the Chorokhi river on the Black Sea. [SUPPORTED: https://en.wikipedia.org/wiki/Gonio_(fortress)]; The fortress lies on the left bank of the Chorokhi near the Black Sea coast. [SUPPORTED: https://visitbatumi.com/en/fortresses-092/Gonio-Apsaros-fortress]; The walls still keep 18 towers today. [SUPPORTED: https://visitbatumi.com/en/fortresses-092/Gonio-Apsaros-fortress]; The walls originally had 22 towers, of which 18 survive. [SUPPORTED: https://en.wikipedia.org/wiki/Gonio_(fortress)]; Its oldest mention comes from Pliny the Elder. [SUPPORTED: https://en.wikipedia.org/wiki/Gonio_(fortress)]; The mention by Pliny the Elder (Natural History) dates to the 1st century AD. [SUPPORTED: https://en.wikipedia.org/wiki/Gonio_(fortress)]"}]'::jsonb);

DO $$
DECLARE
    bad      INTEGER;
    moved    INTEGER := 0;
    expected INTEGER := 50;
    r        RECORD;
BEGIN
    -- expected is the plan's own row count, rendered here, and not a second count of the
    -- temp table the loop below iterates: counting the same table twice would make the
    -- comparison after the loop a tautology. The instance that makes a short loop
    -- unreachable is apply_remediation_change, which raises unless exactly one row
    -- matched; this guard is what reports a loop that changed fewer rows than the plan.

    -- scope guard 1: every planned row is a card_stats row of a curated site that still exists
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN card_stats t ON t.site_id = p.site_id
      LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE t.site_id IS NULL OR u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        -- the source name is a RAISE argument, never part of the quoted message: a name
        -- spliced into the message text only parses while the name happens to contain no
        -- quote, which is a property of today's value and not of this code. G0's guard is
        -- the shape this one copies.
        RAISE EXCEPTION 'teaser card: % planned row(s) are not % sites', bad, 'ancient_nerds';
    END IF;

    -- scope guard 2: the plan is a set of real changes, each one writable in its column
    -- (compared in the column's own type; CASE, because only CASE fixes the order in
    -- which the casts are evaluated)
    SELECT count(*) INTO bad FROM _teaser_card_plan p
     WHERE p.new_value = '' OR CASE p.column_name
                WHEN 'card_description' THEN p.new_value::character varying IS NOT DISTINCT FROM p.old_value::character varying OR length(p.new_value) > 200
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) are not writable changes', bad;
    END IF;

    -- scope guard 3: every planned row still holds the old value the plan names
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.old_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the planned old value', bad;
    END IF;

    -- scope guard 5: every planned row still holds the input its value was derived from
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id, premise FROM _teaser_card_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE (coalesce(u.raw_data -> '_card_provenance' ->> 'text_sha256', '') || '|' || coalesce(u.raw_data -> '_card_provenance' ->> 'desc_sha256', '') || '|' || encode(sha256(convert_to(coalesce(u.description, ''), 'UTF8')), 'hex')) IS DISTINCT FROM p.premise;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the premise the plan derived its value from', bad;
    END IF;

    -- the only writer: the conditional UPDATE and its journal row commit together, and
    -- the function raises unless exactly one row matched
    FOR r IN SELECT * FROM _teaser_card_plan ORDER BY site_id, column_name LOOP
        moved := moved + apply_remediation_change(
            'card_stats', r.column_name, 'site_id', r.site_id::text,
            r.old_value, r.new_value,
            'WB/teaser-card', 'wb-teaser-card-s016-rollback', r.change_key, 'opus-checked', r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'teaser card: % row(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned row now holds the new value
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.new_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) do not hold the new value', bad;
    END IF;

    -- invariant 2: the journal and the data agree, row for row, in both directions
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN remediation_change_log l
        ON l.row_pk = p.site_id::text AND l.table_name = 'card_stats'
       AND l.column_name = p.column_name
       AND l.run_stamp = 'wb-teaser-card-s016-rollback'
     WHERE l.id IS NULL
        OR l.new_value IS DISTINCT FROM p.new_value
        OR l.old_value IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) have no matching journal row', bad;
    END IF;

    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = 'wb-teaser-card-s016-rollback'
       AND (l.table_name <> 'card_stats' OR l.column_name NOT IN ('card_description'));
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: this run stamp journalled % row(s) outside card_stats.(card_description)', bad;
    END IF;

    RAISE NOTICE 'teaser card: % of % planned cell(s) changed and journalled over 50 curated site(s)',
        moved, expected;
END $$;

ROLLBACK;
-- after ROLLBACK of the reversal: the reversal must leave nothing behind either
WITH planned(site_id, column_name, written) AS (VALUES ('e34f699d-7025-4f41-ab0c-fdb54d6a672c'::uuid, 'card_description', 'Less than a mile east of the main ruins at Delphi, twenty Doric columns ringed the circular Tholos of Delphi, and its metopes showed scenes from Amazon and Centaur battles.'), ('e427d7bf-01bd-4238-b972-b0ff62511a9e'::uuid, 'card_description', 'Near the hills of Kyffhäuser, the Leubingen Tumulus, an Early Bronze Age princely grave of about 1940 BC, still rises 7 metres. At its centre lay the body of a man about 50 years old.'), ('e45af002-3182-479c-984e-0692325c40c7'::uuid, 'card_description', 'In Benevento, the Roman Theatre that Hadrian built in 126 AD was abandoned in Lombard times and is now surrounded by the medieval Triggio district. One passage keeps its mosaic pavement.'), ('e4b003f4-3f62-4689-9af9-4b7f120614af'::uuid, 'card_description', 'Ptolemy''s Geographia names a town, Navalia, recently linked to Essen. Its name translates from Latin as dock or wharf, maybe by coincidence, and copyists'' mistakes polluted its coordinates.'), ('e4f6fa32-6aff-4539-b40b-ab73f9e94cec'::uuid, 'card_description', 'At Sammallahdenmäki in Rauma, the Kirkonlaattia, or Church Floor, is a rectangular cairn of granite boulders covering 16 x 19 metres, with a flat top. Volter Högman excavated it in 1891.'), ('e59e7ff4-2392-4365-ab67-2b7fc0d90472'::uuid, 'card_description', 'Buried deep in the Late Classic Acropolis of Copán, the Margarita Tomb held a Maya woman''s remains covered in cinnabar and hematite, a vaulted stairway joining its upper and lower chambers.'), ('e5efe12c-25a8-423f-8974-98fc23e299e9'::uuid, 'card_description', 'Almost 100 meters long and lined with Doric columns, the Echo Stoa stands in the sanctuary of Zeus at Olympia. It is said one word uttered in its hall would echo seven times.'), ('e60fc487-9fb9-4e37-b590-4a035e591c7e'::uuid, 'card_description', 'A flood destroyed its earliest version in the 7th century BC, an arsonist burned its more elaborate rebuilding in 356 BC, and still the Temple of Artemis-Selçuk at Ephesus rose again.'), ('e7c32c5c-3f26-483a-9d49-75ad5003c44b'::uuid, 'card_description', 'Found by chance in 1929 on the River Dee, the Heronbridge Roman Site had stone buildings and a quayside cut into the bedrock. Digs found human remains with evidence of violent deaths.'), ('e7cc2c23-894f-456c-b88b-66bd9e52ad0f'::uuid, 'card_description', 'In the prefecture of Evros lies the Macedonian Tomb of Elafochori, dating to the end of the 4th century BC: a tomb of the Macedonian type, yet with special morphological features of its own.'), ('e8235f8c-e30c-4c97-8297-639b2681d46b'::uuid, 'card_description', 'Near the Malangen fjord, a hunting culture left the Rock Carvings at Åsli: at least 15 worn figures, among them at least eight reindeer, porpoise, a boat and possibly a moose.'), ('e8ecb6c3-4f2c-4505-9b66-ac3743b02e54'::uuid, 'card_description', 'On a hill in ancient Colchis, the Vani Archaeological Site gave up a 4th-century BC signet-ring bearing the name of Dedatos, probably a local ruler. The city''s ancient name is unknown.'), ('e9e6da5f-9c61-444a-aa39-6a2a690813b7'::uuid, 'card_description', 'Kʼatepan translates as old church. Two large terraces set against a mountainside stand behind its plaza, where the Maya temple''s collapsed corner reveals finely cut stonework beneath.'), ('ea13709c-21ca-4d9b-9ccf-578e07e1c2ca'::uuid, 'card_description', 'Crikvenica grew over Ad Turres, a Roman settlement and military base. At Igralište, a Roman workshop made amphorae and pottery from the late 1st century BC to the end of the 2nd century AD.'), ('eb379653-acb9-464d-af06-a0c15a7d6304'::uuid, 'card_description', 'Epidaurum was destroyed by Avars and Slavic invaders in the 7th century. Its refugees fled to the nearby island of Laas, from which Ragusa was founded, in time to become Dubrovnik.'), ('eb482c92-0104-4243-8ae6-0316f0bdec37'::uuid, 'card_description', 'The Dimini area holds a Neolithic settlement and a Mycenean one. Dimini culture is well known for abstract painted vessels; Dimini ware has been identified as far away as Cakran in Albania.'), ('eb752f57-8327-43bc-b6c4-98fa1f0a7ac2'::uuid, 'card_description', 'From around 3000 BC, the Hartberg Megalithic Tomb held bones and a small beaker that suggests use, perhaps with interruptions, for around 1,000 years. Iron Age builders took its slabs.'), ('ec987c81-f12a-429d-b312-7bd15d98412c'::uuid, 'card_description', 'In the Puuc region, the Maya city of Uxmal raises its Pyramid of the Magician in five oval levels, unusual among Maya structures, amid buildings noted for their size and decoration.'), ('eecda91b-c255-4362-a7ed-1beac2c13869'::uuid, 'card_description', 'In Newport, Pembrokeshire, a 4-metre-long capstone rests on smaller rocks: Carreg Coetan Arthur, a Neolithic burial chamber from around 3000 BC that would once have been earth covered.'), ('efe2bc83-83cc-4393-b725-a18543dc9d5f'::uuid, 'card_description', NULL), ('eff62515-9b70-43cc-afe6-c803dd4b5bc3'::uuid, 'card_description', 'On the edge of the Western Desert, the Giza Necropolis holds the Great Pyramid, the pyramids of Khafre and Menkaure, temples, cemeteries, a workers'' village and the Great Sphinx.'), ('f04199e9-626c-4eda-bccf-0395ef21d332'::uuid, 'card_description', 'Near Koblenz, the ancient earthworks of the Goloring draw a circle in the land: a ditch 175 metres in diameter, about 80 cm deep, its outside embankment extending to 190 metres.'), ('f0e4bbe8-a16f-46af-a1fe-0ba46a127c89'::uuid, 'card_description', 'Where the Ceyhan breaks through the Misis Mountains rises Sirkeli Höyüğü, one of the largest settlement mounds of Cilicia, spread over approximately 80 ha, 40 kilometers east of Adana.'), ('f281f0f2-0912-4870-b2d9-f58aa283c9a3'::uuid, 'card_description', 'Layers of time at Desborough Castle: a Norman ringwork partly over a mound, possibly a barrow reused as a Saxon moot, both inside a square enclosure, possibly Iron Age or Late Bronze Age.'), ('f29afd0d-6fb8-4405-bee8-c1b17a6989e3'::uuid, 'card_description', 'On the New River, halfway between Cerros and Lamanai, lies San Estevan, a Maya regional political center from the Late Formative on, where Mound XV still rises 15 m, the highest remaining.'), ('f4e3fdef-07f1-4327-b0db-c01c671bfafc'::uuid, 'card_description', 'At the foot of Slieve Gullion, the granite capstone of Ballykeel Dolmen balances on the tips of three portal stones. Its chamber held three highly decorated Ballyalton bowls.'), ('f524b8bf-c69d-4dd3-8fb6-549de566d297'::uuid, 'card_description', 'On the slopes of Blue Bell Hill in Kent, the White Horse Stone took on the name and folklore of a second stone destroyed before 1834. Near it, excavators found an Early Neolithic longhouse.'), ('f5893102-13b9-44a0-bc87-8348f7da115c'::uuid, 'card_description', 'On a hill spur near Kronach, the Heunischenburg is the oldest known and investigated stone fortification north of the Alps. Its sandstone wall probably burned down during a battle.'), ('f5e7956b-9aa4-47b0-b88a-3ed159f451d1'::uuid, 'card_description', 'Llansteffan Castle rests within the earthwork rings of a much older Iron Age promontory fort. The original earthworks can still be seen, and were used as part of its defence system.'), ('f6916087-0021-44fe-af7e-5111e67f660a'::uuid, 'card_description', 'Found around 1938 as a quarry began work, Risovača Cave held worked flint tools and bone artifacts in its sediments, attributed to Neanderthals at the end of the Middle Paleolithic.'), ('f6b5aa36-d662-4490-a83b-1e5d857afdd5'::uuid, 'card_description', 'Where the Via Appia last touched the sea lay Sinuessa, near thermal springs Pliny says were esteemed a remedy for barrenness in women and insanity in men. The emperor Claudius came too.'), ('f7ed0deb-1206-4b70-b798-80ad7d442261'::uuid, 'card_description', 'Celts lived at Maastricht around 500 BC, where the Meuse ran shallow and easy to cross. It is not known when the Romans came, but in the 1st century AD they bridged the river here.'), ('f80f56c0-949f-4009-8658-f47cc3ca13fa'::uuid, 'card_description', 'Near Mingora in Swat, the Butkara Stupa was dressed in Hellenistic decorations in the 2nd century BCE. At the base of an Indo-Corinthian capital lay buried a reliquary and a coin of Azes II.'), ('f8ccb519-328b-4b91-8c67-3416ee2aa788'::uuid, 'card_description', 'On Gozo, Santa Verna takes its name from a chapel of Saint Venera that once stood close to the temple. Excavations in 2015 revealed the temple''s five-apsed plan of the Ġgantija phase.'), ('f947a367-a17a-4cb3-9d43-93965c88d3bf'::uuid, 'card_description', 'On the coastal plain of Veracruz, the stones of Zempoala came from the nearby river, covered in lime burned from shells and snails. At its peak it held between 25,000 and 30,000 people.'), ('f978251d-d093-415a-8be0-c0e0de5d9d8e'::uuid, 'card_description', 'Vinovia, a Roman fort on a hill 15 metres above the Wear, was probably built to guard Dere Street''s crossing. By the early 6th century its buildings were being demolished for materials.'), ('f9cfcc0f-960a-4184-b72d-ab054ed01221'::uuid, 'card_description', 'At Krasnyi Yar, a large Botai culture site in Kazakhstan, the only livestock bones found were horses: eaten, likely held in corrals, their bones made into tools for working leather.'), ('f9f8e1fa-4460-419a-97cf-1e0e2fb6a565'::uuid, 'card_description', 'On the slopes of Mount Othrys, Xyniae once controlled the passages by the lake that took its name. Plundered in 198 BC, it later saw a castle rise amid the ruins of its ancient acropolis.'), ('fa2bcb15-3d7f-4c62-8215-514ae296e375'::uuid, 'card_description', 'Windmill Hill, the largest known causewayed enclosure in Britain, rings its hilltop with three segmented ditches, the outermost 365 metres across, crossed by causeways up to 7 m wide.'), ('fae3bb4b-85fb-427a-a896-f32f4a2aa69c'::uuid, 'card_description', 'Three round barrows, and possibly a long chambered one, make up Battlegore Burial Chamber in Somerset, where bronze finds include a rapier, a spearhead, a winged axe and a broken dagger.'), ('fc337c87-1194-4407-b440-2b91f93dbdc7'::uuid, 'card_description', NULL), ('fc9b4ac3-3e4a-42d0-96f1-81f37f246230'::uuid, 'card_description', 'The Forum Baths of Roman Trier stayed in use through the end of the fourth century. Then Trier was sacked again and again; from the 13th century the ruins were quarried for local buildings.'), ('fcc4232a-0c79-42c7-ae83-cb6bd8fa98bd'::uuid, 'card_description', 'On the eastern outskirts of Mġarr, the two adjacent Ta'' Ħaġrat Temples stand on the site of a village that predates them. Sir Temi Zammit excavated the site between 1923 and 1926.'), ('fce614a8-8697-45d3-9574-4b092231b0bd'::uuid, 'card_description', 'In the upper Asón River valley, El Mirón Cave holds Upper Paleolithic art and the skeleton of the Red Lady, a woman estimated to have died around 18,700 years ago, discovered only in 2010.'), ('fd2f475b-845a-42ec-8183-264673911980'::uuid, 'card_description', 'Just north of Bad Buchau, the lake Federsee is surrounded by moorland, partially overgrown with reeds. Its basin is famous for excavations of Stone Age and Bronze Age artifacts.'), ('fe021c51-e3fb-407d-9f6c-b770ba056f15'::uuid, 'card_description', 'Bacho Kiro Cave is a four-storey labyrinth of galleries and corridors, 3,600 m long in total. It yielded the oldest human remains ever found in Bulgaria, shown to be those of Homo sapiens.'), ('fee01523-1686-437c-97ef-9e3566fba1c3'::uuid, 'card_description', 'On a steep scarp near the summit of Craig y Llyn, Foel Chwern, a Bronze Age burial cairn of small stones, looks far to the north. A partial dig found neither burials nor any other finds.'), ('ff136c0c-2d3a-4621-b27b-294758b9cc4d'::uuid, 'card_description', 'Probably the last treasury built in the sanctuary of Apollo at Delphi, the Treasury of Cyrene faced his temple, a Doric building raised in marble from Paros and Mount Pentelikon.'), ('ff55d038-92b0-4fad-9973-96cab63ec8db'::uuid, 'card_description', 'A sphinx brought from Egypt stands before the Temple of Jupiter in Diocletian''s Palace. When the emperor unexpectedly abdicated in 305, work stopped, leaving parts of the temple unfinished.'), ('ff7fc6c8-04f1-4988-954c-99c9b9f113e4'::uuid, 'card_description', 'At the mouth of the Chorokhi river on the Black Sea, the Roman walls of Gonio Fortress still keep 18 of their 22 towers. Its oldest mention comes from Pliny the Elder, in the 1st century AD.'))
SELECT 'journal rows for the rollback stamp' AS metric, count(*)::text AS value
  FROM remediation_change_log WHERE run_stamp = 'wb-teaser-card-s016-rollback'
UNION ALL
SELECT 'planned rows still holding the written value', count(*)::text
  FROM planned p JOIN card_stats t ON t.site_id = p.site_id
 WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS NOT DISTINCT FROM p.written::character varying
                ELSE false END
UNION ALL
SELECT 'curated sites', count(*)::text
  FROM unified_sites WHERE source_id = 'ancient_nerds'
UNION ALL
SELECT 'temp table _teaser_card_plan left behind',
       (to_regclass('pg_temp._teaser_card_plan') IS NOT NULL)::int::text
